def read_from_fd(self, buf: Union[bytearray, memoryview]) -> Optional[int]:
    try:
        return self._fio.readinto(buf)  # type: ignore
    except (IOError, OSError) as e:
        if errno_from_exception(e) == errno.EBADF:
            # If the writing half of a pipe is closed, select will
            # report it as readable but reads will fail with EBADF.
            self.close(exc_info=e)
            return None
        else:
            raise
    finally:
        del buf

def test_dhcp_output_error_stream(
    self, m_wait, m_which, m_subp, m_kill, m_getppid, m_remove
):
    """ "dhcp_log_func is called with the output and error streams of
    dhclient when the callable is passed."""
    dhclient_err = "FAKE DHCLIENT ERROR"
    dhclient_out = "FAKE DHCLIENT OUT"
    m_subp.return_value = (dhclient_out, dhclient_err)
    tmpdir = self.tmp_dir()
    lease_content = dedent(
        """
            lease {
              interface "eth9";
              fixed-address 192.168.2.74;
              option subnet-mask 255.255.255.0;
              option routers 192.168.2.1;
            }
        """
    )
    lease_file = os.path.join(tmpdir, "dhcp.leases")
    write_file(lease_file, lease_content)
    pid_file = os.path.join(tmpdir, "dhclient.pid")
    my_pid = 1
    write_file(pid_file, "%d\n" % my_pid)
    m_getppid.return_value = 1  # Indicate that dhclient has daemonized

    def dhcp_log_func(out, err):
        self.assertEqual(out, dhclient_out)
        self.assertEqual(err, dhclient_err)

    IscDhclient().dhcp_discovery(
        "eth9", dhcp_log_func=dhcp_log_func, distro=MockDistro()
    )

def _try_validate_cpus_mem(self) -> None:
    if self.cpus is None and self.memory is None:
        return
    if self.instance_type is not None:
        # The assertion should be true because we have already executed
        # _try_validate_instance_type() before this method.
        # The _try_validate_instance_type() method infers and sets
        # self.cloud if self.instance_type is not None.
        assert self.cloud is not None
        cpus, mem = self.cloud.get_vcpus_mem_from_instance_type(self.instance_type)
        if self.cpus is not None:
            if self.cpus.endswith("+"):
                if cpus < float(self.cpus[:-1]):
                    with ux_utils.print_exception_no_traceback():
                        raise ValueError(
                            f"{self.instance_type} does not have enough "
                            f"vCPUs. {self.instance_type} has {cpus} "
                            f"vCPUs, but {self.cpus} is requested."
                        )
            elif cpus != float(self.cpus):
                with ux_utils.print_exception_no_traceback():
                    raise ValueError(
                        f"{self.instance_type} does not have the requested "
                        f"number of vCPUs. {self.instance_type} has {cpus} "
                        f"vCPUs, but {self.cpus} is requested."
                    )
        if self.memory is not None:
            if self.memory.endswith("+"):
                if mem < float(self.memory[:-1]):
                    with ux_utils.print_exception_no_traceback():
                        raise ValueError(
                            f"{self.instance_type} does not have enough "
                            f"memory. {self.instance_type} has {mem} GB "
                            f"memory, but {self.memory} is requested."
                        )
            elif mem != float(self.memory):
                with ux_utils.print_exception_no_traceback():
                    raise ValueError(
                        f"{self.instance_type} does not have the requested "
                        f"memory. {self.instance_type} has {mem} GB "
                        f"memory, but {self.memory} is requested."
                    )

def _try_validate_ports(self) -> None:
    if self.ports is None:
