def __new__(cls, name, bases, attrs):
    new_class = super().__new__(cls, name, bases, attrs)

    opts = new_class._meta

    if not opts.instance_loader_class:
        opts.instance_loader_class = ModelInstanceLoader

    if opts.model:
        model_opts = opts.model._meta
        declared_fields = new_class.fields

        field_list = []
        for f in sorted(model_opts.fields + model_opts.many_to_many):
            if opts.fields is not None and f.name not in opts.fields:
                continue
            if opts.exclude and f.name in opts.exclude:
                continue

            if f.name in declared_fields:
                # If model field is declared in `ModelResource`, remove it from `declared_fields`
                # to keep exact order of model fields
                field = declared_fields.pop(f.name)
            else:
                field = new_class.field_from_django_field(f.name, f, readonly=False)

            field_list.append(
                (
                    f.name,
                    field,
                )
            )

        # Order as model fields first then declared fields by default
        new_class.fields = OrderedDict([*field_list, *new_class.fields.items()])

        # add fields that follow relationships
        if opts.fields is not None:
            field_list = []
            for field_name in opts.fields:
                if field_name in declared_fields:
                    continue
                if field_name.find("__") == -1:
                    continue

                model = opts.model
                attrs = field_name.split("__")
                for i, attr in enumerate(attrs):
                    verbose_path = ".".join(
                        [opts.model.__name__] + attrs[0 : i + 1]
                    )

                    try:
                        f = model._meta.get_field(attr)
                    except FieldDoesNotExist as e:
                        logger.debug(e, exc_info=e)
                        raise FieldDoesNotExist(
                            "%s: %s has no field named '%s'"
                            % (verbose_path, model.__name__, attr)
                        )

                    if i < len(attrs) - 1:
                        # We're not at the last attribute yet, so check
                        # that we're looking at a relation, and move on to
                        # the next model.
                        if isinstance(f, ForeignObjectRel):
                            model = get_related_model(f)
                        else:
                            if get_related_model(f) is None:
                                raise KeyError(
                                    "%s is not a relation" % verbose_path
                                )
                            model = get_related_model(f)

                if isinstance(f, ForeignObjectRel):
                    f = f.field

                field = new_class.field_from_django_field(
                    field_name, f, readonly=True
                )
                field_list.append((field_name, field))

            new_class.fields.update(OrderedDict(field_list))

    return new_class

def test_api_gef_memory_parse_info_proc_maps(self):
    gdb, gef, root = self._gdb, self._gef, self._conn.root
    gdb.execute("start")

    Section = root.eval("Section")

    if self.gdb_version < (11, 0):
        # expect an exception
        with pytest.raises(AttributeError):
            next(gef.memory.parse_gdb_info_proc_maps())

    else:
        for section in gef.memory.parse_gdb_info_proc_maps():
            assert isinstance(section, Section)

def fd(self) -> int:
    assert(gef and gef.libc.version)
    if gef.libc.version < (2, 32):
        return self._chunk.fd
    return self.reveal_ptr(self.data_address)

def protect_ptr(self, pos: int, pointer: int) -> int:
    """https://elixir.bootlin.com/glibc/glibc-2.32/source/malloc/malloc.c#L339"""
    assert(gef and gef.libc.version)
    if gef.libc.version < (2, 32):
        return pointer
    return (pos >> 12) ^ pointer

def reveal_ptr(self, pointer: int) -> int:
    """https://elixir.bootlin.com/glibc/glibc-2.32/source/malloc/malloc.c#L341"""
    assert(gef and gef.libc.version)
    if gef.libc.version < (2, 32):
        return pointer
    return gef.memory.read_integer(pointer) ^ (pointer >> 12)

def target_remote_posthook():
    if gef.session.remote_initializing:
        return

    gef.session.remote = GefRemoteSessionManager("", 0)
    if not gef.session.remote.setup():
        raise EnvironmentError(f"Failed to create a proper environment for {gef.session.remote}")

def _is_registered_causal_lm(model: transformers.PreTrainedModel) -> bool:
    """Return True if model class is either a registered 🤗 Causal LM or a subclass of one"""
    try:
        from transformers.models.auto.modeling_auto import MODEL_FOR_CAUSAL_LM_MAPPING
    except ImportError as e:
        raise MissingConditionalImportError(extra_deps_group='nlp',
                                            conda_package='transformers',
                                            conda_channel='conda-forge') from e

    # This try/except is needed until https://github.com/huggingface/transformers/issues/26778
    # is resolved in a release. This means that this attempt to automatically detect causal LMs
    # does not currently work in an environment with flash attention <2 installed.
    try:
        causal_lm_classes = list(MODEL_FOR_CAUSAL_LM_MAPPING.values())
    except RuntimeError as e:
        if 'Failed to import transformers.models' in str(e):
            MODEL_FOR_CAUSAL_LM_MAPPING = {}
            return False
        else:
            raise e
    return any(isinstance(model, causal_lm_class) for causal_lm_class in causal_lm_classes)

def get_hf_config_from_composer_state_dict(state_dict: Dict[str, Any],
                                           config_overrides: Optional[Dict[str, Any]] = None) -> 'PretrainedConfig':
    """Get a HuggingFace config from a composer state dict with overrides applied

    Args:
        state_dict (Dict[str, Any]): The state dict to get the config from
        config_overrides (Dict[str, Any], optional): Any overrides to apply to the config

    Returns:
        transformers.PretrainedConfig: The HuggingFace config
    """
    try:
        import transformers
    except ImportError as e:
        raise MissingConditionalImportError(extra_deps_group='nlp',
                                            conda_package='transformers',
                                            conda_channel='conda-forge') from e

    if config_overrides is None:
        config_overrides = {}

    hf_config_dict = state_dict['state']['integrations']['huggingface']['model']['config']['content']
    # Update the config with any extra args needed
    hf_config_dict.update(config_overrides)
    # JSON keys need to be converted back to ints, huggingface does not auto convert them along this code path
    if 'id2label' in hf_config_dict:
        hf_config_dict['id2label'] = {int(k): v for k, v in hf_config_dict['id2label'].items()}

    try:
        return transformers.AutoConfig.for_model(**hf_config_dict)
    except ValueError:
        try:
            return transformers.AutoConfig.from_pretrained(hf_config_dict['_name_or_path'], **hf_config_dict)
        except KeyError:
            raise Exception(
                f'Could not load config from state dict using either `for_model` or `from_pretrained`.'
                f'Please make sure that the model_type={hf_config_dict.get("model_type")} is valid, or that the'
                f'config has a valid `_name_or_path`.')

def __init__(self, sub_stat: str = "mean"):
    self.variance = stats.Var()
    self.sub_stat = sub_stat

    if self.sub_stat == "mean":
        self.subtracted_statistic_estimator = stats.Mean()
    elif self.sub_stat == "median":
        self.subtracted_statistic_estimator = stats.Quantile(q=0.5)
    else:
        raise ValueError(
            f"Unknown subtracted statistic {self.sub_stat}, expected one of median, mean."
        )

def __getitem__(self, name: str) -> str:
    value = self.get(name)
    if value is None:
        raise KeyError(name)
    return value

def get(  # type: ignore
    self,
    name: str,
    default: typing.Optional[str] = None,
    domain: typing.Optional[str] = None,
    path: typing.Optional[str] = None,
) -> typing.Optional[str]:
    """
    Get a cookie by name. May optionally include domain and path
    in order to specify exactly which cookie to retrieve.
    """
    value = None
    for cookie in self.jar:
        if cookie.name == name:
            if domain is None or cookie.domain == domain:
                if path is None or cookie.path == path:
                    if value is not None:
                        message = f"Multiple cookies exist with name={name}"
                        raise CookieConflict(message)
                    value = cookie.value

    if value is None:
        return default
    return value

def get_ground_truth_bbox_annotations(
    img_idx: int, image_path: str, batch: Dict, class_name_map: Dict = None
) -> List[Dict[str, Any]]:
    """Get ground truth bounding box annotation data in the form required for `wandb.Image` overlay system."""
    indices = batch["batch_idx"] == img_idx
    bboxes = batch["bboxes"][indices]
    cls_labels = batch["cls"][indices].squeeze(1).tolist()

    class_name_map_reverse = {v: k for k, v in class_name_map.items()}

    if len(bboxes) == 0:
        wandb.termwarn(
            f"Image: {image_path} has no bounding boxes labels", repeat=False
        )
        return None

    cls_labels = batch["cls"][indices].squeeze(1).tolist()
    if class_name_map:
        cls_labels = [str(class_name_map[label]) for label in cls_labels]

    original_image_shape = batch["ori_shape"][img_idx]
    resized_image_shape = batch["resized_shape"][img_idx]
    ratio_pad = batch["ratio_pad"][img_idx]

    data = []
    for box, label in zip(bboxes, cls_labels):
        box = scale_bounding_box_to_original_image_shape(
            box, resized_image_shape, original_image_shape, ratio_pad
        )
        data.append(
            {
                "position": {
                    "middle": [int(box[0]), int(box[1])],
                    "width": int(box[2]),
                    "height": int(box[3]),
                },
                "domain": "pixel",
                "class_id": class_name_map_reverse[label],
                "box_caption": label,
            }
        )

    return data

