    table: wandb.Table,
    max_validation_batches: int,
    epoch: Optional[int] = None,
) -> wandb.Table:
    """Plot validation results in a table."""
    data_idx = 0
    for batch_idx, batch in enumerate(dataloader):
        for img_idx, image_path in enumerate(batch["im_file"]):
            prediction_result = predictor(image_path)[0]
            _, prediction_box_data, mean_confidence_map = plot_predictions(
                prediction_result, model_name
            )
            try:
                ground_truth_data = get_ground_truth_bbox_annotations(
                    img_idx, image_path, batch, class_label_map
                )
                wandb_image = wandb.Image(
                    image_path,
                    boxes={
                        "ground-truth": {
                            "box_data": ground_truth_data,
                            "class_labels": class_label_map,
                        },
                        "predictions": {
                            "box_data": prediction_box_data["box_data"],
                            "class_labels": class_label_map,
                        },
                    },
                )
                table_rows = [
                    data_idx,
                    batch_idx,
                    wandb_image,
                    mean_confidence_map,
                    prediction_result.speed,
                ]
                table_rows = [epoch] + table_rows if epoch is not None else table_rows
                table_rows = [model_name] + table_rows
                table.add_data(*table_rows)
                data_idx += 1
            except TypeError:
                pass
        if batch_idx + 1 == max_validation_batches:
            break
    return table

def _initialize_from_data(
    self,
    data: "ImageDataType",
    mode: Optional[str] = None,
) -> None:
    pil_image = util.get_module(
        "PIL.Image",
        required='wandb.Image needs the PIL package. To get it, run "pip install pillow".',
    )
    if util.is_matplotlib_typename(util.get_full_typename(data)):
        buf = BytesIO()
        util.ensure_matplotlib_figure(data).savefig(buf, format='png')
        self._image = pil_image.open(buf, formats=["PNG"])
    elif isinstance(data, pil_image.Image):
        self._image = data
    elif util.is_pytorch_tensor_typename(util.get_full_typename(data)):
        vis_util = util.get_module(
            "torchvision.utils", "torchvision is required to render images"
        )
        if hasattr(data, "requires_grad") and data.requires_grad:
            data = data.detach()  # type: ignore
        if hasattr(data, "dtype") and str(data.dtype) == "torch.uint8":
            data = data.to(float)
        data = vis_util.make_grid(data, normalize=True)
        self._image = pil_image.fromarray(
            data.mul(255).clamp(0, 255).byte().permute(1, 2, 0).cpu().numpy()
        )
    else:
        if hasattr(data, "numpy"):  # TF data eager tensors
            data = data.numpy()
        if data.ndim > 2:
            data = data.squeeze()  # get rid of trivial dimensions as a convenience
        self._image = pil_image.fromarray(
            self.to_uint8(data), mode=mode or self.guess_mode(data)
        )

    tmp_path = os.path.join(MEDIA_TMP.name, runid.generate_id() + ".png")
    self.format = "png"
    assert self._image is not None
    self._image.save(tmp_path, transparency=None)
    self._set_file(tmp_path, is_tmp=True)

def get_function_contents_by_name(lines: List[str], name: str):
    """
    Extracts a function from `lines` of segmented source code with the name `name`.

    Args:
        lines (`List[str]`):
            Source code of a script seperated by line.
        name (`str`):
            The name of the function to extract. Should be either `training_function` or `main`
    """
    if name != "training_function" and name != "main":
        raise ValueError(f"Incorrect function name passed: {name}, choose either 'main' or 'training_function'")
    good_lines, found_start = [], False
    for line in lines:
        if not found_start and f"def {name}" in line:
            found_start = True
            good_lines.append(line)
            continue
        if found_start:
            if name == "training_function" and "def main" in line:
                return good_lines
            if name == "main" and "if __name__" in line:
                return good_lines
            good_lines.append(line)

