def props_to_json_schema(input_dict, required_fields=None):
    schema: Dict[str, Any] = {"type": "object", "properties": {}, "required": required_fields or []}

    def infer_array_item_type(prop):
        type_map = {
            "string": "string",
            "int": "number",
            "float": "number",
            "dict": "object",
            "list": "array",
            "bool": "boolean",
            "none": "null",
        }
        if prop.get("items", {}).get("type"):
            return prop["items"]["type"]
        if "prefill" in prop and prop["prefill"] and len(prop["prefill"]) > 0:
            return type_map.get(type(prop["prefill"][0]).__name__.lower(), "string")
        if "default" in prop and prop["default"] and len(prop["default"]) > 0:
            return type_map.get(type(prop["default"][0]).__name__.lower(), "string")
        return "string"  # Fallback for arrays like searchStringsArray

    for key, value in input_dict.items():
        prop_schema: Dict[str, Any] = {}
        prop_type = value.get("type")

        if "enum" in value:
            prop_schema["enum"] = value["enum"]

        if "default" in value:
            prop_schema["default"] = value["default"]
        elif "prefill" in value:
            prop_schema["default"] = value["prefill"]

        if "description" in value:
            prop_schema["description"] = value["description"]

        # Handle Apify special types first
        if prop_type == "object" and value.get("editor") == "proxy":
            prop_schema["type"] = "object"
            prop_schema["properties"] = {
                "useApifyProxy": {
                    "title": "Use Apify Proxy",
                    "type": "boolean",
                    "description": "Whether to use Apify Proxy - ALWAYS SET TO TRUE.",
                    "default": True,
                    "examples": [True],
                }
            }
            prop_schema["required"] = ["useApifyProxy"]
            if "default" in value:
                prop_schema["default"] = value["default"]

        elif prop_type == "array" and value.get("editor") == "requestListSources":
            prop_schema["type"] = "array"
            prop_schema["items"] = {
                "type": "object",
                "title": "Request list source",
                "description": "Request list source",
                "properties": {
                    "url": {"title": "URL", "type": "string", "description": "URL of the request list source"}
                },
            }

        elif prop_type == "array":
            prop_schema["type"] = "array"
            prop_schema["items"] = {
                "type": infer_array_item_type(value),
                "title": value.get("title", "Item"),
                "description": "Item",
            }

        elif prop_type == "object":
            prop_schema["type"] = "object"
            if "default" in value:
                prop_schema["default"] = value["default"]
                prop_schema["properties"] = {}
                for k, v in value.get("properties", value["default"]).items():
                    prop_type = v["type"] if isinstance(v, dict) else type(v).__name__.lower()
                    if prop_type == "bool":
                        prop_type = "boolean"
                    prop_schema["properties"][k] = {"type": prop_type}

        else:
            prop_schema["type"] = prop_type

        schema["properties"][key] = prop_schema

    return schema

def get_changed_files(repo_root: Path, base_ref: str = "main") -> list[Path]:
    """Use git to get the list of files changed compared to the base branch."""
    try:
        cmd = ["git", "diff", "--name-only", f"{base_ref}...HEAD"]
        result = subprocess.run(cmd, cwd=repo_root, text=True, capture_output=True)
        if result.returncode != 0:
            raise RuntimeError(f"Git command failed: {result.stderr}")

        return [repo_root / Path(f) for f in result.stdout.splitlines() if f.strip()]
    except Exception as e:
        print(f"Exception occurred: {e!s}")
        raise

def test(
    obj: dict,
    fail_fast: bool,
    cov: bool,
    cov_fail_under: int,
    base_ref: str,
    workers: int,
    package_names: tuple,
):
    # Fail on incompatible configurations
    if cov_fail_under and not cov:
        raise click.UsageError(
            "You have to pass --cov in order to use --cov-fail-under"
        )

    if base_ref is not None and not base_ref:
        raise click.UsageError("Option '--base-ref' cannot be empty.")

    if not package_names and not base_ref:
        raise click.UsageError(
            "Either pass '--base-ref' or provide at least one package name."
        )

    console = obj["console"]
    repo_root = obj["repo_root"]
    debug: bool = obj["debug"]
    packages_to_test: set[Path] = set()
    all_packages = find_all_packages(repo_root)

    if package_names:
        changed_packages: set[Path] = {repo_root / Path(pn) for pn in package_names}
    else:
        # Get the files that changed from the base branch
        changed_files = get_changed_files(repo_root, base_ref)
        # Get the packages containing the changed files
        changed_packages = get_changed_packages(changed_files, all_packages)

    # Find the dependants of the changed packages
    # Skip dependants if we're checking coverage
    if cov:
        dependants = set()
    else:
        dependants = get_dependants_packages(changed_packages, all_packages)

    # Test the packages directly affected and their dependants
    packages_to_test = changed_packages | dependants

    # Test the packages using a process pool
    results = []
    with concurrent.futures.ProcessPoolExecutor(max_workers=int(workers)) as executor:
        future_to_package = {
            executor.submit(
                _run_tests,
                package_path,
                changed_packages,
                base_ref,
                cov,
                cov_fail_under,
            ): package_path
            for package_path in sorted(packages_to_test)
        }

        for future in concurrent.futures.as_completed(future_to_package):
            result = future.result()
            results.append(result)

            # Print results as they complete
            package: Path = result["package"]
            package_name = package.relative_to(repo_root)
            if result["status"] == ResultStatus.INSTALL_FAILED:
                console.print(f"❗ Unable to build package {package_name}")
                console.print(
                    _trim(debug, f"Error:\n{result['stderr']}"), style="warning"
                )
            elif result["status"] == ResultStatus.TESTS_PASSED:
                console.print(f"✅ {package_name} succeeded in {result['time']}")
            elif result["status"] == ResultStatus.UNSUPPORTED_PYTHON_VERSION:
                console.print(
                    f"⏭️ {package_name} skipped due to python version incompatibility"
                )
                console.print(
                    _trim(debug, f"Error:\n{result['stderr']}"), style="warning"
                )
            elif result["status"] == ResultStatus.NO_TESTS:
                console.print(f"⏭️ {package_name} skipped due to no tests")
                console.print(
                    _trim(debug, f"Error:\n{result['stderr']}"), style="warning"
                )
            else:
                console.print(f"❌ {package_name} failed")
                console.print(
                    _trim(debug, f"Error:\n{result['stderr']}"), style="error"
                )
                console.print(
                    _trim(debug, f"Output:\n{result['stdout']}"), style="info"
                )

    # Print summary
    failed = [
        r["package"].relative_to(repo_root)
        for r in results
        if r["status"] in (ResultStatus.TESTS_FAILED, ResultStatus.COVERAGE_FAILED)
    ]
    install_failed = [
        r["package"].relative_to(repo_root)
        for r in results
        if r["status"] == ResultStatus.INSTALL_FAILED
    ]
    skipped_no_tests = [
        r["package"].relative_to(repo_root)
        for r in results
        if r["status"] == ResultStatus.NO_TESTS
        and "package has no tests" in r["stderr"]
    ]
    skipped_pyversion_incompatible = [
        r["package"].relative_to(repo_root)
        for r in results
        if r["status"] == ResultStatus.UNSUPPORTED_PYTHON_VERSION
        and "Not compatible with Python" in r["stderr"]
    ]

    if skipped_pyversion_incompatible:
        console.print(
            f"\n{len(skipped_pyversion_incompatible)} packages were skipped due to Python version incompatibility:"
        )
        for p in skipped_pyversion_incompatible:
            print(p)
    if skipped_no_tests:
        console.print(
            f"\n{len(skipped_no_tests)} packages were skipped because they have no tests:"
        )
        for p in skipped_no_tests:
            print(p)

    if install_failed:
        # Do not fail the CI if there was an installation problem: many packages cannot
        # be installed in the runners, something we should either fix or ignore.
        console.print(f"\n{len(install_failed)} packages could not be installed:")
        for p in install_failed:
            print(p)

    if failed:
        console.print(f"\n{len(failed)} packages had test failures:")
        for p in failed:
            console.print(p)
        exit(1)
    else:
        console.print(
            f"\nTests passed for {len(results) - len(skipped_no_tests) - len(skipped_pyversion_incompatible)} packages.",
            style="green",
        )

def process_item(
    self, item: Any, spider: Spider | None = None
) -> Deferred[list[FileInfoOrError]]:
    info = self.spiderinfo
    requests = arg_to_iter(self.get_media_requests(item, info))
    dlist = [self._process_request(r, info, item) for r in requests]
    dfd = cast(
        "Deferred[list[FileInfoOrError]]", DeferredList(dlist, consumeErrors=True)
    )
    return dfd.addCallback(self.item_completed, item, info)

def _get_head_plugin(self) -> Any:
    prev = self.file
    for plugin in self.plugins[::-1]:
        prev = plugin(prev, self.feed_options)
    return prev

def setup_method(self):
    try:
        import mitmproxy  # noqa: F401,PLC0415
    except ImportError:
        pytest.skip("mitmproxy is not installed")

    self._oldenv = os.environ.copy()
    self._proxy = MitmProxy()
    proxy_url = self._proxy.start(listen_host=self.proxy_host)
    os.environ["https_proxy"] = proxy_url
    os.environ["http_proxy"] = proxy_url

def teardown_method(self):
    self._proxy.stop()
    os.environ = self._oldenv

def run_python_tests(args: Any, go_proc: 'Optional[GoProc]' = None) -> None:
    tests = find_all_tests()

    def print_go() -> None:
        stdout, rc = go_proc.wait()
        if go_proc.returncode == 0 and tests._tests:
            print(f'All Go tests succeeded, ran in {go_proc.runtime:.1f} seconds', flush=True)
        else:
            print(stdout, end='', flush=True)
        return rc

    if args.module:
        tests = filter_tests_by_module(tests, args.module)
        if not tests._tests:
            if go_proc:
                raise SystemExit(print_go())
            raise SystemExit('No test module named %s found' % args.module)

    if args.name:
        tests = filter_tests_by_name(tests, *args.name)
        if not tests._tests and not go_proc:
            raise SystemExit('No test named %s found' % args.name)
    if tests._tests:
        python_tests_ok = run_cli(tests, args.verbosity)
    else:
        python_tests_ok = True
    exit_code = 0 if python_tests_ok else 1
    if go_proc:
        print_go()
        if exit_code == 0:
            exit_code = go_proc.returncode
    if exit_code != 0:
        print("\x1b[31mError\x1b[39m: Some tests failed!")
    raise SystemExit(exit_code)

def format_user_message_content(
    self,
    signature: type[Signature],
    inputs: dict[str, Any],
    prefix: str = "",
    suffix: str = "",
    main_request: bool = False,
) -> str:
    messages = [prefix]
    for k, v in signature.input_fields.items():
        if k in inputs:
            value = inputs.get(k)
            formatted_field_value = format_field_value(field_info=v, value=value)
            messages.append(f"[[ ## {k} ## ]]\n{formatted_field_value}")

    if main_request:
        output_requirements = self.user_message_output_requirements(signature)
        if output_requirements is not None:
            messages.append(output_requirements)

    messages.append(suffix)
    return "\n\n".join(messages).strip()

def format_assistant_message_content(
    self,
    signature: type[Signature],
    outputs: dict[str, Any],
    missing_field_message=None,
) -> str:
    assistant_message_content = self.format_field_with_value(
        {
            FieldInfoWithName(name=k, info=v): outputs.get(k, missing_field_message)
            for k, v in signature.output_fields.items()
        },
    )
    assistant_message_content += "\n\n[[ ## completed ## ]]\n"
    return assistant_message_content

