def register_callback_api_routes(
    self, callback_api_paths: Dict[str, Callable[..., Any]]
):
    """
    Register callback API endpoints on the Flask app.
    Each key in callback_api_paths is a route, each value is a handler (sync or async).
    The view function parses the JSON body and passes it to the handler.
    """
    for path, handler in callback_api_paths.items():
        endpoint = f"dash_callback_api_{path}"
        route = path if path.startswith("/") else f"/{path}"
        methods = ["POST"]

        if inspect.iscoroutinefunction(handler):

            async def _async_view_func(*args, handler=handler, **kwargs):
                data = request.get_json()
                result = await handler(**data) if data else await handler()
                return jsonify(result)

            view_func = _async_view_func
        else:

            def _sync_view_func(*args, handler=handler, **kwargs):
                data = request.get_json()
                result = handler(**data) if data else handler()
                return jsonify(result)

            view_func = _sync_view_func

            view_func = _sync_view_func

        # Flask 2.x+ supports async views natively
        self.server.add_url_rule(
            route, endpoint=endpoint, view_func=view_func, methods=methods
        )

def checkAndReloadIfNeeded(self):
    now = int(time.time() * 1000)
    if now - self.memory_cache["last_check"] < CACHE_CHECK_INTERVAL_MS:
        return
    self.memory_cache["last_check"] = now

    try:
        file_path = self.getCredentialFilePath()
        stat = file_path.stat()
        file_mod_time = int(stat.st_mtime * 1000)
        if file_mod_time > self.memory_cache["file_mod_time"]:
            await self.reloadCredentialsFromFile()
            self.memory_cache["file_mod_time"] = file_mod_time
    except FileNotFoundError:
        self.memory_cache["file_mod_time"] = 0
    except Exception as e:
        self.memory_cache["credentials"] = None
        raise TokenManagerError(TokenError.FILE_ACCESS_ERROR, str(e), e)

    def _load_plugin(self, plugin_path, args=None, config=None):
        """Load the plugin, init it and add to the _plugin dict."""
        # Load the plugin class
        try:
            # Import the plugin
            plugin = import_module('glances.plugins.' + plugin_path)
            # Init and add the plugin to the dictionary
            if hasattr(plugin, 'PluginModel'):
                # Old fashion way to load the plugin (before Glances 5.0)
                # Should be removed in Glances 5.0 - see #3170
                self._plugins[plugin_path] = getattr(plugin, 'PluginModel')(args=args, config=config)
                logger.warning(
                    f'The {plugin_path} plugin class name is "PluginModel" and it is deprecated, \
please rename it to "{plugin_path.capitalize()}Plugin"'
                )
            elif hasattr(plugin, plugin_path.capitalize() + 'Plugin'):
                # New fashion way to load the plugin (after Glances 5.0)
                self._plugins[plugin_path] = getattr(plugin, plugin_path.capitalize() + 'Plugin')(
                    args=args, config=config
                )
        except Exception as e:
            # If a plugin can not be loaded, display a critical message
            # on the console but do not crash
            logger.critical(f"Error while initializing the {plugin_path} plugin ({e})")
            logger.error(traceback.format_exc())
            # An error occurred, disable the plugin
            if args is not None:
                setattr(args, 'disable_' + plugin_path, False)
        else:
            # Manage the default status of the plugin (enable or disable)
            if args is not None:
                # If the all keys are set in the disable_plugin option then look in the enable_plugin option
                if getattr(args, 'disable_all', False):
                    logger.debug('%s => %s', plugin_path, getattr(args, 'enable_' + plugin_path, False))
                    setattr(args, 'disable_' + plugin_path, not getattr(args, 'enable_' + plugin_path, False))
                else:
                    setattr(args, 'disable_' + plugin_path, getattr(args, 'disable_' + plugin_path, False))

def end(self):
    """End of the Glances stats."""
    # Close export modules
    for e in self._exports:
        self._exports[e].exit()
    # Close plugins
    for p in self._plugins:
        self._plugins[p].exit()
        self._plugins[p].exit()

class Export(GlancesExport):
    """This class manages the Prometheus export module."""

    METRIC_SEPARATOR = '_'

    def __init__(self, config=None, args=None):
        """Init the Prometheus export IF."""
        super().__init__(config=config, args=args)

        # Load the Prometheus configuration file section
        self.export_enable = self.load_conf('prometheus', mandatories=['host', 'port', 'labels'], options=['prefix'])
        if not self.export_enable:
            exit('Missing PROMETHEUS config')

        # Optionals configuration keys
        if self.prefix is None:
            self.prefix = 'glances'

        if self.labels is None:
            self.labels = 'src:glances'

        # Init the metric dict
        # Perhaps a better method is possible...
        self._metric_dict = {}

        self._stats = GlancesStats()

        # Init the Prometheus Exporter
        self.init()

    def init(self):
        """Init the Prometheus Exporter"""
        try:
            start_http_server(port=int(self.port), addr=self.host)
        except Exception as e:
            logger.critical(f"Can not start Prometheus exporter on {self.host}:{self.port} ({e})")
            sys.exit(2)
        else:
            logger.info(f"Start Prometheus exporter on {self.host}:{self.port}")

    def export(self, name, columns, points):
        """Write the points to the Prometheus exporter using Gauge."""
        logger.debug(f"Export {name} stats to Prometheus exporter")

        # Remove non number stats and convert all to float (for Boolean)
        data = {str(k): float(v) for k, v in zip(columns, points) if isinstance(v, Number)}

        key_name = self._stats.get_plugin(name).get_key()

        # Write metrics to the Prometheus exporter
        for metric, value in data.items():
            labels = self.labels
            metric_name = self.prefix + self.METRIC_SEPARATOR + name + self.METRIC_SEPARATOR
            try:
                obj, stat = metric.split('.')
                metric_name += stat
                labels += f",{key_name}:{obj}"
            except ValueError:
                metric_name += metric

            # Prometheus is very sensible to the metric name
            # See: https://prometheus.io/docs/practices/naming/
            for c in ' .-/:[]':
                metric_name = metric_name.replace(c, self.METRIC_SEPARATOR)

            # Get the labels
            labels = self.parse_tags(labels)
            # Manage an internal dict between metric name and Gauge
            if metric_name not in self._metric_dict:
                self._metric_dict[metric_name] = Gauge(metric_name, "", labelnames=listkeys(labels))
            # Write the value
            if hasattr(self._metric_dict[metric_name], 'labels'):
                # Add the labels (see issue #1255)
                self._metric_dict[metric_name].labels(**labels).set(value)
            else:
                self._metric_dict[metric_name].set(value)

def test_batched_transcribe(physcisworks_path):
    model = WhisperModel("tiny")
    batched_model = BatchedInferencePipeline(model=model)
    result, info = batched_model.transcribe(physcisworks_path, batch_size=16)
    assert info.language == "en"
    assert info.language_probability > 0.7
    segments = []
    for segment in result:
        segments.append(
            {"start": segment.start, "end": segment.end, "text": segment.text}
        )
    # number of near 30 sec segments
    assert len(segments) == 6

    result, info = batched_model.transcribe(
        physcisworks_path,
        batch_size=16,
        without_timestamps=False,
        word_timestamps=True,
    )
    segments = []
    for segment in result:
        assert segment.words is not None
        segments.append(
            {"start": segment.start, "end": segment.end, "text": segment.text}
        )
    assert len(segments) > 7

