def process_docs(dataset: datasets.Dataset) -> datasets.Dataset:
    """Process the SPaRC dataset documents."""

    def _process_doc(doc):
        # Extract and clean the grid visualization if present
        if 'text_visualization' in doc:
            doc['visualization'] = doc['text_visualization']

        # Ensure solutions is a list
        if 'solutions' in doc and isinstance(doc['solutions'], str):
            try:
                doc['solutions'] = json.loads(doc['solutions'])
            except json.JSONDecodeError:
                doc['solutions'] = [doc['solutions']]
        elif 'solutions' in doc and not isinstance(doc['solutions'], list):
            doc['solutions'] = [doc['solutions']]

        # Convert polyshapes if it's a string
        if 'polyshapes' in doc and isinstance(doc['polyshapes'], str):
            try:
                doc['polyshapes'] = json.loads(doc['polyshapes'])
            except json.JSONDecodeError:
                doc['polyshapes'] = {}

        # Extract grid size
        if 'grid_size' in doc:
            if isinstance(doc['grid_size'], dict):
                doc['grid_height'] = doc['grid_size'].get('height', 10)
                doc['grid_width'] = doc['grid_size'].get('width', 10)
            else:
                doc['grid_height'] = 10
                doc['grid_width'] = 10

        return doc

    return dataset.map(_process_doc)

def doc_to_target(doc: Dict[str, Any]) -> str:
    """Extract the target solution and puzzle data for validation."""
    # Create a comprehensive target that includes both the solution and puzzle data
    target_data = {
        "solutions": doc.get('solutions', []),
        "puzzle_array": doc.get('puzzle_array', []),
        "grid_size": doc.get('grid_size', {}),
        "polyshapes": doc.get('polyshapes', {}),
        "difficulty": doc.get('difficulty_level', "unknown")
    }

    # Return as JSON string so metrics can parse it
    return json.dumps(target_data)

def extract_solution_path(
    solution_text: str, puzzle_data: Dict = None
) -> Optional[List[Dict[str, int]]]:
    """Extract solution path from LLM's response

    Args:
        solution_text: Text response from the LLM
        puzzle_data: Optional puzzle data dict to extract end point from

    Returns:
        List of coordinate dicts or None if no path found
    """
    # Avoid noisy prints during evaluation
    # First, check if "Solution" appears in the text
    solution_marker = "####"
    if solution_marker in solution_text:
        # Only process text after "####"
        solution_part = solution_text.split(solution_marker)[-1]
    else:
        # If no solution marker, use the full text
        solution_part = solution_text

    # Look for coordinate patterns like (0,0) -> (0,1) or similar
    # Pattern for (x,y) or (x, y) coordinates
    coord_pattern = r"\((\d+),\s*(\d+)\)"
    coords = re.findall(coord_pattern, solution_part)

    if coords:
        # Extract end point from puzzle data if provided
        end_point = None
        if puzzle_data:
            puzzle_array = puzzle_data.get("puzzle_array", [])
            for y, row in enumerate(puzzle_array):
                for x, cell in enumerate(row):
                    if cell == "E":
                        end_point = {"x": x, "y": y}
                        break
                if end_point:
                    break

        # Convert string coordinates to integer dicts
        path = []
        for x, y in coords:
            point = {"x": int(x), "y": int(y)}
            path.append(point)

            # Stop extracting if we've reached the end point
            if (
                end_point
                and point["x"] == end_point["x"]
                and point["y"] == end_point["y"]
            ):
                break

        return path

    # If no coordinates found, return None
    return None

def count_score(prediction, ground_truth):
    """Score for counting tasks."""
    try:
        # Extract the first number from prediction
        numbers = re.findall(r'\d+', prediction)
        if not numbers:
            return 0.0
        pred_count = int(numbers[0])
        true_count = int(ground_truth)
        return 1.0 if pred_count == true_count else 0.0
    except:
        return 0.0

def process_results_mc(doc, results):
    """Process multiple choice results for LongBench v2 tasks."""
    # For multiple choice, we expect log likelihoods
    gold_idx = doc.get("answer_idx", 0)

    # results should contain log likelihoods for each choice
    if isinstance(results, list) and len(results) > gold_idx:
        # Check if the highest likelihood corresponds to the correct answer
        pred_idx = np.argmax(results)
        return {"acc": 1.0 if pred_idx == gold_idx else 0.0}

    return {"acc": 0.0}

def numeric_match(prediction: str, ground_truth: str, tolerance: float = 0.001) -> float:
    """Check if prediction matches a numeric answer within tolerance."""
    try:
        # Extract numbers from both strings
        pred_nums = re.findall(r'-?\d+\.?\d*', extract_answer(prediction))
        truth_nums = re.findall(r'-?\d+\.?\d*', ground_truth)

        if not pred_nums or not truth_nums:
            # Fall back to exact match if no numbers found
            return exact_match(prediction, ground_truth)

        pred_num = float(pred_nums[0])
        truth_num = float(truth_nums[0])

        return 1.0 if abs(pred_num - truth_num) < tolerance else 0.0
    except:
        # Fall back to exact match if parsing fails
        return exact_match(prediction, ground_truth)

def list_all_tasks(
    self, list_groups=True, list_tags=True, list_subtasks=True
) -> str:
    from pytablewriter import MarkdownTableWriter

    def sanitize_path(path):
        # don't print full path if we are within the lm_eval/tasks dir !
        # if we aren't though, provide the full path.
        if "lm_eval/tasks/" in path:
            return "lm_eval/tasks/" + path.split("lm_eval/tasks/")[-1]
        else:
            return path

    group_table = MarkdownTableWriter()
    group_table.headers = ["Group", "Config Location"]
    gt_values = []
    for g in self.all_groups:
        path = self.task_index[g]["yaml_path"]
        if path == -1:
            path = "---"
        else:
            path = sanitize_path(path)
        gt_values.append([g, path])
    group_table.value_matrix = gt_values

    tag_table = MarkdownTableWriter()
    tag_table.headers = ["Tag"]
    tag_table.value_matrix = [[t] for t in self.all_tags]

    subtask_table = MarkdownTableWriter()
    subtask_table.headers = ["Task", "Config Location", "Output Type"]
    st_values = []
    for t in self.all_subtasks:
        path = self.task_index[t]["yaml_path"]

        output_type = ""

        # read the yaml file to determine the output type
        if path != -1:
            config = utils.load_yaml_config(path, mode="simple")
            if "output_type" in config:
                output_type = config["output_type"]
            elif (
                "include" in config
            ):  # if no output type, check if there is an include with an output type
                include_path = path.split("/")[:-1] + config["include"]
                include_config = utils.load_yaml_config(include_path, mode="simple")
                if "output_type" in include_config:
                    output_type = include_config["output_type"]

        if path == -1:
            path = "---"
        else:
            path = sanitize_path(path)
        st_values.append([t, path, output_type])
    subtask_table.value_matrix = st_values

    result = "\n"
    if list_groups:
        result += group_table.dumps() + "\n\n"
    if list_tags:
        result += tag_table.dumps() + "\n\n"
    if list_subtasks:
        result += subtask_table.dumps() + "\n\n"
    return result

def _build_date_trunc(args: t.List[exp.Expression]) -> exp.Expression:
    a0, a1 = seq_get(args, 0), seq_get(args, 1)

    def _is_unit_like(e: exp.Expression | None) -> bool:
        if not (isinstance(e, exp.Literal) and e.is_string):
            return False
        text = e.this
        return not any(ch.isdigit() for ch in text)

    # Determine which argument is the unit
    unit, this = a0, a1 if _is_unit_like(a0) else a1, a0

    return exp.TimestampTrunc(this=this, unit=unit)

