def change_order_status(self, request, order):
    form = self.get_order_status_form()
    if not form.is_valid():
        return self.reload_page(error=_("Invalid form submission"))

    old_status, new_status = order.status, form.cleaned_data["new_status"]
    handler = self.get_handler(user=request.user)

    success_msg = _(
        "Order status changed from '%(old_status)s' to '%(new_status)s'"
    ) % {"old_status": old_status, "new_status": new_status}
    try:
        handler.handle_order_status_change(order, new_status, note_msg=success_msg)
    except PaymentError as e:
        messages.error(
            request,
            _("Unable to change order status due to payment error: %s") % e,
        )
    except order_exceptions.InvalidOrderStatus:
        # The form should validate against this, so we should only end up
        # here during race conditions.
        messages.error(
            request,
            _(
                "Unable to change order status as the requested "
                "new status is not valid"
            ),
        )
    else:
        messages.info(request, success_msg)
    return self.reload_page()

def _export_tablib(self, export_type: str, return_url: str) -> T_RESPONSE:
    """
    Exports a variety of formats using the tablib library.
    """
    if tablib is None:
        raise Exception(
            "Could not import `tablib`. "
            "Enable `export` integration by installing `flask-admin[export]`"
        )

    filename = self.get_export_name(export_type)

    disposition = f"attachment;filename={secure_filename(filename)}"

    mimetype, encoding = mimetypes.guess_type(filename)
    if not mimetype:
        mimetype = "application/octet-stream"
    if encoding:
        mimetype = f"{mimetype}; charset={encoding}"

    ds = tablib.Dataset(headers=[csv_encode(c[1]) for c in self._export_columns])

    count, data = self._export_data()

    for row in data:
        vals = [
            csv_encode(self.get_export_value(row, c[0]))
            for c in self._export_columns
        ]
        ds.append(vals)

    try:
        try:
            response_data = ds.export(format=export_type)
        except AttributeError:
            response_data = getattr(ds, export_type)
    except (AttributeError, tablib.UnsupportedFormat):
        flash(
            gettext('Export type "%(type)s" is not supported.', type=export_type),
            "error",
        )
        return redirect(return_url)

    return Response(
        response_data,
        headers={"Content-Disposition": disposition},
        mimetype=mimetype,
    )

