def has_permissions_predicate(
    permission_level: PermissionLevel = PermissionLevel.REGULAR,
):
    async def predicate(ctx):
        return await check_permissions(ctx, ctx.command.qualified_name)

    predicate.permission_level = permission_level
    return predicate

async def check_permissions(ctx, command_name) -> bool:
    """Logic for checking permissions for a command for a user"""
    if await ctx.bot.is_owner(ctx.author) or ctx.author.id == ctx.bot.user.id:
        # Bot owner(s) (and creator) has absolute power over the bot
        return True

    permission_level = ctx.bot.command_perm(command_name)

    if permission_level is PermissionLevel.INVALID:
        logger.warning("Invalid permission level for command %s.", command_name)
        return True

    if (
        permission_level is not PermissionLevel.OWNER
        and ctx.channel.permissions_for(ctx.author).administrator
        and ctx.guild == ctx.bot.modmail_guild
    ):
        # Administrators have permission to all non-owner commands in the Modmail Guild
        logger.debug("Allowed due to administrator.")
        return True

    command_permissions = ctx.bot.config["command_permissions"]
    checkables = {*ctx.author.roles, ctx.author}

    if command_name in command_permissions:
        # -1 is for @everyone
        if -1 in command_permissions[command_name] or any(
            str(check.id) in command_permissions[command_name] for check in checkables
        ):
            return True

    level_permissions = ctx.bot.config["level_permissions"]

    for level in PermissionLevel:
        if level >= permission_level and level.name in level_permissions:
            # -1 is for @everyone
            if -1 in level_permissions[level.name] or any(
                str(check.id) in level_permissions[level.name] for check in checkables
            ):
                return True
    return False

def github_token_required(ignore_if_not_heroku=False):
    """
    A decorator that ensures github token
    is set
    """

    async def predicate(ctx):
        if ignore_if_not_heroku and ctx.bot.hosting_method != HostingMethod.HEROKU:
            return True
        else:
            return ctx.bot.config.get("github_token")

    predicate.fail_msg = (
        "You can only use this command if you have a "
        "configured `GITHUB_TOKEN`. Get a "
        "personal access token from developer settings."
    )
    return commands.check(predicate)

def __init__(self, argument: str, *, now: Optional[datetime.datetime] = None):
    match = self.compiled.fullmatch(argument)
    if match is None or not match.group(0):
        match = self.discord_fmt.fullmatch(argument)
        if match is not None:
            self.dt = datetime.datetime.utcfromtimestamp(int(match.group("ts")), tz=datetime.timezone.utc)
            return
        else:
            raise commands.BadArgument("invalid time provided")

    data = {k: int(v) for k, v in match.groupdict(default=0).items()}
    now = now or datetime.datetime.now(datetime.timezone.utc)
    self.dt = now + relativedelta(**data)

def __init__(self, argument: str, *, now: Optional[datetime.datetime] = None):
    try:
        o = ShortTime(argument, now=now)
    except Exception:
        super().__init__(argument)
    else:
        self.dt = o.dt
        self._past = False

async def transform(self, interaction, value: str) -> datetime.datetime:
    now = interaction.created_at
    try:
        short = ShortTime(value, now=now)
    except commands.BadArgument:
        try:
            human = FutureTime(value, now=now)
        except commands.BadArgument as e:
            raise BadTimeTransform(str(e)) from None
        else:
            return human.dt
    else:
        return short.dt

def __init__(self, dt: datetime.datetime, now: datetime.datetime = None):
    self.dt = dt
    self.now = now

    if now is None:
        self.now = dt
    else:
        self.now = now

    self.arg = ""

def _resolve_user(self, user_str):
    """Helper to resolve a user from mention, ID, or username."""
    import re

    if not user_str:
        return None
    if user_str.isdigit():
        return int(user_str)
    match = re.match(r"<@!?(\d+)>", user_str)
    if match:
        return int(match.group(1))
    return None

async def setup(self, ctx):
    """
    Sets up a server for Modmail.

    You only need to run this command
    once after configuring Modmail.
    """

    if ctx.guild != self.bot.modmail_guild:
        return await ctx.send(f"You can only setup in the Modmail guild: {self.bot.modmail_guild}.")

    if self.bot.main_category is not None:
        logger.debug("Can't re-setup server, main_category is found.")
        return await ctx.send(f"{self.bot.modmail_guild} is already set up.")

    if self.bot.modmail_guild is None:
        embed = discord.Embed(
            title="Error",
            description="Modmail functioning guild not found.",
            color=self.bot.error_color,
        )
        return await ctx.send(embed=embed)

    overwrites = {
        self.bot.modmail_guild.default_role: discord.PermissionOverwrite(read_messages=False),
        self.bot.modmail_guild.me: discord.PermissionOverwrite(read_messages=True),
    }

    for level in PermissionLevel:
        if level <= PermissionLevel.REGULAR:
            continue
        permissions = self.bot.config["level_permissions"].get(level.name, [])
        for perm in permissions:
            perm = int(perm)
            if perm == -1:
                key = self.bot.modmail_guild.default_role
            else:
                key = self.bot.modmail_guild.get_member(perm)
                if key is None:
                    key = self.bot.modmail_guild.get_role(perm)
            if key is not None:
                logger.info("Granting %s access to Modmail category.", key.name)
                overwrites[key] = discord.PermissionOverwrite(read_messages=True)

    category = await self.bot.modmail_guild.create_category(name="Modmail", overwrites=overwrites)

    await category.edit(position=0)

    log_channel = await self.bot.modmail_guild.create_text_channel(name="bot-logs", category=category)

    embed = discord.Embed(
        title="Friendly Reminder",
        description=f"You may use the `{self.bot.prefix}config set log_channel_id "
        "<channel-id>` command to set up a custom log channel, then you can delete this default "
        f"{log_channel.mention} log channel.",
        color=self.bot.main_color,
    )

    embed.add_field(
        name="Thanks for using our bot!",
        value="If you like what you see, consider giving the "
        "[repo a star](https://github.com/modmail-dev/modmail) :star: and if you are "
        "feeling extra generous, buy us coffee on [Patreon](https://patreon.com/kyber) :heart:!",
    )

    embed.set_footer(text=f'Type "{self.bot.prefix}help" for a complete list of commands.')
    await log_channel.send(embed=embed)

    self.bot.config["main_category_id"] = category.id
    self.bot.config["log_channel_id"] = log_channel.id

    await self.bot.config.update()
    await ctx.send(
        "**Successfully set up server.**\n"
        "Consider setting permission levels to give access to roles "
        "or users the ability to use Modmail.\n\n"
        f"Type:\n- `{self.bot.prefix}permissions` and `{self.bot.prefix}permissions add` "
        "for more info on setting permissions.\n"
        f"- `{self.bot.prefix}config help` for a list of available customizations."
    )

    if not self.bot.config["command_permissions"] and not self.bot.config["level_permissions"]:
        await self.bot.update_perms(PermissionLevel.REGULAR, -1)
        for owner_id in self.bot.bot_owner_ids:
            await self.bot.update_perms(PermissionLevel.OWNER, owner_id)

def parse_user_or_role(ctx, user_or_role):
    mention = None
    if user_or_role is None:
        mention = ctx.author.mention
    elif hasattr(user_or_role, "mention"):
        mention = user_or_role.mention
    elif user_or_role in {"here", "everyone", "@here", "@everyone"}:
        mention = "@" + user_or_role.lstrip("@")
    return mention

async def process_dm_modmail(self, message: discord.Message) -> None:
    """Processes messages sent to the bot."""
    blocked = await self._process_blocked(message)
    if blocked:
        return
    sent_emoji, blocked_emoji = await self.retrieve_emoji()

    # Handle forwarded messages (Discord forwards)
    # See: https://discord.com/developers/docs/resources/message#message-reference-content-attribution-forwards
    # 1. Multi-forward (message_snapshots)
    if hasattr(message, "flags") and getattr(message.flags, "has_snapshot", False):
        if hasattr(message, "message_snapshots") and message.message_snapshots:
            thread = await self.threads.find(recipient=message.author)
            if thread is None:
                delta = await self.get_thread_cooldown(message.author)
                if delta:
                    await message.channel.send(
                        embed=discord.Embed(
                            title=self.config["cooldown_thread_title"],
                            description=self.config["cooldown_thread_response"].format(delta=delta),
                            color=self.error_color,
                        )
                    )
                    return
                if self.config["dm_disabled"] in (DMDisabled.NEW_THREADS, DMDisabled.ALL_THREADS):
                    embed = discord.Embed(
                        title=self.config["disabled_new_thread_title"],
                        color=self.error_color,
                        description=self.config["disabled_new_thread_response"],
                    )
                    embed.set_footer(
                        text=self.config["disabled_new_thread_footer"],
                        icon_url=self.get_guild_icon(guild=message.guild, size=128),
                    )
                    logger.info(
                        "A new thread was blocked from %s due to disabled Modmail.", message.author
                    )
                    await self.add_reaction(message, blocked_emoji)
                    return await message.channel.send(embed=embed)
                thread = await self.threads.create(message.author, message=message)
            else:
                if self.config["dm_disabled"] == DMDisabled.ALL_THREADS:
                    embed = discord.Embed(
                        title=self.config["disabled_current_thread_title"],
                        color=self.error_color,
                        description=self.config["disabled_current_thread_response"],
                    )
                    embed.set_footer(
                        text=self.config["disabled_current_thread_footer"],
                        icon_url=self.get_guild_icon(guild=message.guild, size=128),
                    )
                    logger.info("A message was blocked from %s due to disabled Modmail.", message.author)
                    await self.add_reaction(message, blocked_emoji)
                    return await message.channel.send(embed=embed)
            # Extract forwarded content using utility function
            combined_content = extract_forwarded_content(message) or "[Forwarded message with no content]"

            class ForwardedMessage:
                def __init__(self, original_message, forwarded_content):
                    self.author = original_message.author
                    self.content = forwarded_content
                    self.attachments = []
                    self.stickers = []
                    self.created_at = original_message.created_at
                    self.embeds = []
                    self.id = original_message.id
                    self.flags = original_message.flags
                    self.message_snapshots = original_message.message_snapshots
                    self.type = getattr(original_message, "type", None)

            forwarded_msg = ForwardedMessage(message, combined_content)
            await thread.send(forwarded_msg)
            await self.add_reaction(message, sent_emoji)
            self.dispatch("thread_reply", thread, False, message, False, False)
            return
        else:
            message.content = "[Forwarded message with no content]"
    # 2. Single-message forward (MessageType.forward)
    elif getattr(message, "type", None) == getattr(discord.MessageType, "forward", None):
        # Check for message.reference and its type
        ref = getattr(message, "reference", None)
        if ref and getattr(ref, "type", None) == getattr(discord, "MessageReferenceType", None).forward:
            # Try to fetch the referenced message
            ref_msg = None
            try:
                if ref.resolved:
                    ref_msg = ref.resolved
                elif ref.message_id and ref.channel_id:
                    channel = self.get_channel(ref.channel_id) or (
                        await self.fetch_channel(ref.channel_id)
                    )
                    ref_msg = await channel.fetch_message(ref.message_id)
            except Exception:
                ref_msg = None
            if ref_msg:
                # Forward the referenced message as if it was sent
                thread = await self.threads.find(recipient=message.author)
                if thread is None:
                    delta = await self.get_thread_cooldown(message.author)
                    if delta:
                        await message.channel.send(
                            embed=discord.Embed(
                                title=self.config["cooldown_thread_title"],
                                description=self.config["cooldown_thread_response"].format(delta=delta),
                                color=self.error_color,
                            )
                        )
                        return
                    if self.config["dm_disabled"] in (DMDisabled.NEW_THREADS, DMDisabled.ALL_THREADS):
                        embed = discord.Embed(
                            title=self.config["disabled_new_thread_title"],
                            color=self.error_color,
                            description=self.config["disabled_new_thread_response"],
                        )
                        embed.set_footer(
                            text=self.config["disabled_new_thread_footer"],
                            icon_url=self.get_guild_icon(guild=message.guild, size=128),
                        )
                        logger.info(
                            "A new thread was blocked from %s due to disabled Modmail.", message.author
                        )
                        await self.add_reaction(message, blocked_emoji)
                        return await message.channel.send(embed=embed)
                    thread = await self.threads.create(message.author, message=message)
                else:
                    if self.config["dm_disabled"] == DMDisabled.ALL_THREADS:
                        embed = discord.Embed(
                            title=self.config["disabled_current_thread_title"],
                            color=self.error_color,
                            description=self.config["disabled_current_thread_response"],
                        )
                        embed.set_footer(
                            text=self.config["disabled_current_thread_footer"],
                            icon_url=self.get_guild_icon(guild=message.guild, size=128),
                        )
                        logger.info(
                            "A message was blocked from %s due to disabled Modmail.", message.author
                        )
                        await self.add_reaction(message, blocked_emoji)
                        return await message.channel.send(embed=embed)

                # Create a forwarded message wrapper to preserve forward info
                class ForwardedMessage:
                    def __init__(self, original_message, ref_message):
                        self.author = original_message.author
                        # Use the utility function to extract content or fallback to ref message content
                        extracted_content = extract_forwarded_content(original_message)
                        self.content = (
                            extracted_content
                            or ref_message.content
                            or "[Forwarded message with no text content]"
                        )
                        self.attachments = getattr(ref_message, "attachments", [])
                        self.stickers = getattr(ref_message, "stickers", [])
                        self.created_at = original_message.created_at
                        self.embeds = getattr(ref_message, "embeds", [])
                        self.id = original_message.id
                        self.type = getattr(original_message, "type", None)
                        self.reference = original_message.reference

                forwarded_msg = ForwardedMessage(message, ref_msg)
                await thread.send(forwarded_msg)
                await self.add_reaction(message, sent_emoji)
                self.dispatch("thread_reply", thread, False, message, False, False)
                return
            else:
                message.content = "[Forwarded message with no content]"

    if message.type not in [discord.MessageType.default, discord.MessageType.reply]:
        return

    thread = await self.threads.find(recipient=message.author)
    if thread and thread.snoozed:
        await thread.restore_from_snooze()
        self.threads.cache[thread.id] = thread
        # Update the DB with the new channel_id after restoration
        if thread.channel:
            await self.api.logs.update_one(
                {"recipient.id": str(thread.id)}, {"$set": {"channel_id": str(thread.channel.id)}}
            )
    # Re-fetch the thread object to ensure channel is valid
    thread = await self.threads.find(recipient=message.author)

    if thread is None:
        delta = await self.get_thread_cooldown(message.author)
        if delta:
            await message.channel.send(
                embed=discord.Embed(
                    title=self.config["cooldown_thread_title"],
                    description=self.config["cooldown_thread_response"].format(delta=delta),
                    color=self.error_color,
                )
            )
            return

        if self.config["dm_disabled"] in (DMDisabled.NEW_THREADS, DMDisabled.ALL_THREADS):
            embed = discord.Embed(
                title=self.config["disabled_new_thread_title"],
                color=self.error_color,
                description=self.config["disabled_new_thread_response"],
            )
            embed.set_footer(
                text=self.config["disabled_new_thread_footer"],
                icon_url=self.get_guild_icon(guild=message.guild, size=128),
            )
            logger.info("A new thread was blocked from %s due to disabled Modmail.", message.author)
            await self.add_reaction(message, blocked_emoji)
            return await message.channel.send(embed=embed)

        thread = await self.threads.create(message.author, message=message)
    else:
        if self.config["dm_disabled"] == DMDisabled.ALL_THREADS:
            embed = discord.Embed(
                title=self.config["disabled_current_thread_title"],
                color=self.error_color,
                description=self.config["disabled_current_thread_response"],
            )
            embed.set_footer(
                text=self.config["disabled_current_thread_footer"],
                icon_url=self.get_guild_icon(guild=message.guild, size=128),
            )
            logger.info("A message was blocked from %s due to disabled Modmail.", message.author)
            await self.add_reaction(message, blocked_emoji)
            return await message.channel.send(embed=embed)

    if not thread.cancelled:
        try:
            await thread.send(message)
        except Exception:
            logger.error("Failed to send message:", exc_info=True)
            await self.add_reaction(message, blocked_emoji)
        else:
            for user in thread.recipients:
                # send to all other recipients
                if user != message.author:
                    try:
                        await thread.send(message, user)
                    except Exception:
                        # silently ignore
                        logger.error("Failed to send message:", exc_info=True)

            await self.add_reaction(message, sent_emoji)
            self.dispatch("thread_reply", thread, False, message, False, False)

async def format_cog_help(self, cog, *, no_cog=False):
    bot = self.context.bot
    prefix = self.context.clean_prefix

    formats = [""]
    for cmd in await self.filter_commands(
        cog.get_commands() if not no_cog else cog,
        sort=True,
        key=lambda c: (bot.command_perm(c.qualified_name), c.qualified_name),
    ):
        perm_level = bot.command_perm(cmd.qualified_name)
        if perm_level is PermissionLevel.INVALID:
            format_ = f"`{prefix + cmd.qualified_name}` "
        else:
            format_ = f"`[{perm_level}] {prefix + cmd.qualified_name}` "

        format_ += f"- {cmd.short_doc}\n" if cmd.short_doc else "- *No description.*\n"
        if not format_.strip():
            continue
        if len(format_) + len(formats[-1]) >= 1024:
            formats.append(format_)
        else:
            formats[-1] += format_

    embeds = []
    for format_ in formats:
        description = (
            cog.description or "No description."
            if not no_cog
            else "Miscellaneous commands without a category."
        )
        embed = discord.Embed(description=f"*{description}*", color=bot.main_color)

        if not format_:
            continue

        embed.add_field(name="Commands", value=format_ or "No commands.")

        name = cog.qualified_name + " - Help" if not no_cog else "Miscellaneous Commands"
        embed.set_author(
            name=name, icon_url=bot.user.display_avatar.url if bot.user.display_avatar else None
        )

        embed.set_footer(
            text=f'Type "{prefix}{self.command_attrs["name"]} command" '
            "for more info on a specific command."
        )
        embeds.append(embed)

    if len(embeds) > 1:
        for n, em in enumerate(embeds):
            em.set_author(name=f"{em.author.name} [{n + 1}]", icon_url=em.author.icon_url)

    return embeds

async def send_error_message(self, error):
    command = self.context.kwargs.get("command")
    val = self.context.bot.snippets.get(command)
    if val is not None:
        embed = discord.Embed(title=f"{command} is a snippet.", color=self.context.bot.main_color)
        embed.add_field(name=f"`{command}` will send:", value=val, inline=False)

        snippet_aliases = []
        for alias in self.context.bot.aliases:
            if self.context.bot._resolve_snippet(alias) == command:
                snippet_aliases.append(f"`{alias}`")

        if snippet_aliases:
            embed.add_field(
                name="Aliases to this snippet:", value=",".join(snippet_aliases), inline=False
            )

        return await self.get_destination().send(embed=embed)

    val = self.context.bot.aliases.get(command)
    if val is not None:
        values = utils.parse_alias(val)

        if not values:
            embed = discord.Embed(
                title="Error",
                color=self.context.bot.error_color,
                description=f"Alias `{command}` is invalid, this alias will now be deleted."
                "This alias will now be deleted.",
            )
            embed.add_field(name=f"{command}` used to be:", value=val)
            self.context.bot.aliases.pop(command)
            await self.context.bot.config.update()
        else:
            if len(values) == 1:
                embed = discord.Embed(title=f"{command} is an alias.", color=self.context.bot.main_color)
                embed.add_field(name=f"`{command}` points to:", value=values[0])
            else:
                embed = discord.Embed(
                    title=f"{command} is an alias.",
                    color=self.context.bot.main_color,
                    description=f"**`{command}` points to the following steps:**",
                )
                for i, val in enumerate(values, start=1):
                    embed.add_field(name=f"Step {i}:", value=val)

        embed.set_footer(
            text=f'Type "{self.context.clean_prefix}{self.command_attrs["name"]} alias" '
            "for more details on aliases."
        )
        return await self.get_destination().send(embed=embed)

    logger.warning("CommandNotFound: %s", error)

    embed = discord.Embed(color=self.context.bot.error_color)
    embed.set_footer(text=f'Command/Category "{command}" not found.')

    choices = set()

    for cmd in self.context.bot.walk_commands():
        if not cmd.hidden:
            choices.add(cmd.qualified_name)

    closest = get_close_matches(command, choices)
    if closest:
        embed.add_field(name="Perhaps you meant:", value="\n".join(f"`{x}`" for x in closest))
    else:
        embed.title = "Cannot find command or category"
        embed.set_footer(
            text=f'Type "{self.context.clean_prefix}{self.command_attrs["name"]}" '
            "for a list of all available commands."
        )
    await self.get_destination().send(embed=embed)

async def changelog(self, ctx, version: str.lower = ""):
    """Shows the changelog of the Modmail."""
    changelog = await Changelog.from_url(self.bot)
    version = version.lstrip("v") if version else changelog.latest_version.version

    try:
        index = [v.version for v in changelog.versions].index(version)
    except ValueError:
        return await ctx.send(
            embed=discord.Embed(
                color=self.bot.error_color,
                description=f"The specified version `{version}` could not be found.",
            )
        )

    paginator = EmbedPaginatorSession(ctx, *changelog.embeds)
    try:
        paginator.current = index
        await paginator.run()
    except asyncio.CancelledError:
        pass
    except Exception:
        try:
            await paginator.close()
        finally:
            logger.warning("Failed to display changelog.", exc_info=True)
            await ctx.send(
                f"View the changelog here: {changelog.latest_version.changelog_url}#v{version[::2]}"
            )

async def set_presence(self, *, status=None, activity_type=None, activity_message=None):
    if status is None:
        status = self.bot.config.get("status")

    if activity_type is None:
        activity_type = self.bot.config.get("activity_type")

    url = None
    activity_message = (activity_message or self.bot.config["activity_message"]).strip()
    if activity_type is not None and not activity_message:
        logger.warning('No activity message found whilst activity is provided, defaults to "Modmail".')
        activity_message = "Modmail"

    if activity_type == ActivityType.listening:
        if activity_message.lower().startswith("to "):
            # The actual message is after listening to [...]
            # discord automatically add the "to"
            activity_message = activity_message[3:].strip()
    elif activity_type == ActivityType.competing:
        if activity_message.lower().startswith("in "):
            # The actual message is after listening to [...]
            # discord automatically add the "in"
            activity_message = activity_message[3:].strip()
    elif activity_type == ActivityType.streaming:
        url = self.bot.config["twitch_url"]

    if activity_type == ActivityType.custom:
        activity = discord.CustomActivity(name=activity_message)
    elif activity_type is not None:
        activity = discord.Activity(type=activity_type, name=activity_message, url=url)
    else:
        activity = None
    await self.bot.change_presence(activity=activity, status=status)

    return activity, status

async def config_set(self, ctx, key: str.lower, *, value: str):
    """Set a configuration variable and its value."""

    keys = self.bot.config.public_keys

    if key in keys:
        try:
            await self.bot.config.set(key, value)
            await self.bot.config.update()
            embed = discord.Embed(
                title="Success",
                color=self.bot.main_color,
                description=f"Set `{key}` to `{self.bot.config[key]}`.",
            )
        except InvalidConfigError as exc:
            embed = exc.embed
    else:
        embed = discord.Embed(
            title="Error", color=self.bot.error_color, description=f"{key} is an invalid key."
        )
        valid_keys = [f"`{k}`" for k in sorted(keys)]
        embed.add_field(name="Valid keys", value=truncate(", ".join(valid_keys), 1024))

    return await ctx.send(embed=embed)

async def config_get(self, ctx, *, key: str.lower = None):
    """
    Show the configuration variables that are currently set.

    Leave `key` empty to show all currently set configuration variables.
    """
    keys = self.bot.config.public_keys

    if key:
        if key in keys:
            desc = f"`{key}` is set to `{self.bot.config[key]}`"
            embed = discord.Embed(color=self.bot.main_color, description=desc)
            embed.set_author(
                name="Config variable",
                icon_url=self.bot.user.display_avatar.url if self.bot.user.display_avatar else None,
            )

        else:
            embed = discord.Embed(
                title="Error",
                color=self.bot.error_color,
                description=f"`{key}` is an invalid key.",
            )
            embed.set_footer(
                text=f'Type "{self.bot.prefix}config options" for a list of config variables.'
            )

    else:
        embed = discord.Embed(
            color=self.bot.main_color,
            description="Here is a list of currently set configuration variable(s).",
        )
        embed.set_author(
            name="Current config(s):",
            icon_url=self.bot.user.display_avatar.url if self.bot.user.display_avatar else None,
        )
        config = self.bot.config.filter_default(self.bot.config)

        for name, value in config.items():
            if name in self.bot.config.public_keys:
                embed.add_field(name=name, value=f"`{value}`", inline=False)

    return await ctx.send(embed=embed)

def from_string(cls, s, strict=False):
    m = match(r"^@?local/(.+)$", s)
    if m is None:
        if not strict:
            m = match(r"^(.+?)/(.+?)/(.+?)(?:@(.+?))?$", s)
        else:
            m = match(r"^(.+?)/(.+?)/(.+?)@(.+?)$", s)

    if m is not None:
        return Plugin(*m.groups())
    raise InvalidPluginError("Cannot decipher %s.", s)  # pylint: disable=raising-format-tuple

async def plugins_reset(self, ctx):
    """
    Reset all plugins for the bot.

    Deletes all cache and plugins from config and unloads from the bot.
    """
    logger.warning("Purging plugins.")
    for ext in list(self.bot.extensions):
        if not ext.startswith("plugins."):
            continue
        logger.error("Unloading plugin: %s.", ext)
        try:
            plugin = next((p for p in self.loaded_plugins if p.ext_string == ext), None)
            if plugin:
                await self.unload_plugin(plugin)
                self.loaded_plugins.remove(plugin)
            else:
                await self.bot.unload_extension(ext)
        except Exception:
            logger.error("Failed to unload plugin: %s.", ext)

    for module in list(sys.modules.keys()):
        if module.startswith("plugins."):
            del sys.modules[module]

    self.bot.config["plugins"].clear()
    await self.bot.config.update()

    cache_path = Path(__file__).absolute().parent.parent / "temp" / "plugins-cache"
    if cache_path.exists():
        logger.warning("Removing cache path.")
        shutil.rmtree(cache_path)

    for entry in os.scandir(Path(__file__).absolute().parent.parent / "plugins"):
        if entry.is_dir() and entry.name != "@local":
            shutil.rmtree(entry.path)
            logger.warning("Removing %s.", entry.name)

    embed = discord.Embed(
        description="Successfully purged all plugins from the bot.", color=self.bot.main_color
    )
    return await ctx.send(embed=embed)

def has_permissions_predicate(
    permission_level: PermissionLevel = PermissionLevel.REGULAR,
):
    async def predicate(ctx):
        return await check_permissions(ctx, ctx.command.qualified_name)

    predicate.permission_level = permission_level
    return predicate

def github_token_required(ignore_if_not_heroku=False):
    """
    A decorator that ensures github token
    is set
    """

    async def predicate(ctx):
        if ignore_if_not_heroku and ctx.bot.hosting_method != HostingMethod.HEROKU:
            return True
        else:
            return ctx.bot.config.get("github_token")

    predicate.fail_msg = (
        "You can only use this command if you have a "
        "configured `GITHUB_TOKEN`. Get a "
        "personal access token from developer settings."
    )
    return commands.check(predicate)

async def find_log_entry(self, key: str) -> list:
    query = {"key": key}
    projection = {"messages": {"$slice": 5}}
    logger.debug(f"Retrieving log ID {key}.")

    return await self.logs.find(query, projection).to_list(None)

async def search_by_text(self, text: str, limit: Optional[int]):
    return await self.bot.db.logs.find(
        {
            "guild_id": str(self.bot.guild_id),
            "open": False,
            "$text": {"$search": f'"{text}"'},
        },
        {"messages": {"$slice": 5}},
    ).to_list(limit)

async def cancel_closure(self, auto_close: bool = False, all: bool = False) -> None:
    if self.close_task is not None and (not auto_close or all):
        self.close_task.cancel()
        self.close_task = None
    if self.auto_close_task is not None and (auto_close or all):
        self.auto_close_task.cancel()
        self.auto_close_task = None

    to_update = self.bot.config["closures"].pop(str(self.id), None)
    if to_update is not None:
        await self.bot.config.update()

async def find_linked_messages(
    self,
    message_id: typing.Optional[int] = None,
    either_direction: bool = False,
    message1: discord.Message = None,
    note: bool = True,
) -> typing.Tuple[discord.Message, typing.List[typing.Optional[discord.Message]]]:
    if message1 is not None:
        if not message1.embeds or not message1.embeds[0].author.url or message1.author != self.bot.user:
            raise ValueError("Malformed thread message.")

    elif message_id is not None:
        try:
            message1 = await self.channel.fetch_message(message_id)
        except discord.NotFound:
            raise ValueError("Thread message not found.")

        if not (
            message1.embeds
            and message1.embeds[0].author.url
            and message1.embeds[0].color
            and message1.author == self.bot.user
        ):
            raise ValueError("Thread message not found.")

        if message1.embeds[0].footer and "Internal Message" in message1.embeds[0].footer.text:
            if not note:
                raise ValueError("Thread message not found.")
            return message1, None

        if message1.embeds[0].color.value != self.bot.mod_color and not (
            either_direction and message1.embeds[0].color.value == self.bot.recipient_color
        ):
            raise ValueError("Thread message not found.")
    else:
        async for message1 in self.channel.history():
            if (
                message1.embeds
                and message1.embeds[0].author.url
                and message1.embeds[0].color
                and (
                    message1.embeds[0].color.value == self.bot.mod_color
                    or (either_direction and message1.embeds[0].color.value == self.bot.recipient_color)
                )
                and message1.embeds[0].author.url.split("#")[-1].isdigit()
                and message1.author == self.bot.user
            ):
                break
        else:
            raise ValueError("Thread message not found.")

    try:
        joint_id = int(message1.embeds[0].author.url.split("#")[-1])
    except ValueError:
        raise ValueError("Malformed thread message.")

    messages = [message1]
    for user in self.recipients:
        async for msg in user.history():
            if either_direction:
                if msg.id == joint_id:
                    return message1, msg

            if not (msg.embeds and msg.embeds[0].author.url):
                continue
            try:
                if int(msg.embeds[0].author.url.split("#")[-1]) == joint_id:
                    messages.append(msg)
                    break
            except ValueError:
                continue

    if len(messages) > 1:
        return messages

    raise ValueError("DM message not found.")

async def delete_message(
    self, message: typing.Union[int, discord.Message] = None, note: bool = True
) -> None:
    if isinstance(message, discord.Message):
        message1, *message2 = await self.find_linked_messages(message1=message, note=note)
    else:
        message1, *message2 = await self.find_linked_messages(message, note=note)
    tasks = []

    if not isinstance(message, discord.Message):
        tasks += [message1.delete()]

    for m2 in message2:
        if m2 is not None:
            tasks += [m2.delete()]

    if message1.embeds[0].footer and "Persistent Internal Message" in message1.embeds[0].footer.text:
        tasks += [self.bot.api.delete_note(message1.id)]

    if tasks:
        await asyncio.gather(*tasks)

async def edit_dm_message(self, message: discord.Message, content: str) -> None:
    try:
        linked_messages = await self.find_linked_message_from_dm(message)
    except ValueError:
        logger.warning("Failed to edit message.", exc_info=True)
        raise

    for msg in linked_messages:
        embed = msg.embeds[0]
        if isinstance(msg.channel, discord.TextChannel):
            # just for thread channel, we put the old message in embed field
            embed.add_field(name="**Edited, former message:**", value=embed.description)
        embed.description = content
        await asyncio.gather(self.bot.api.edit_message(message.id, content), msg.edit(embed=embed))

async def reply(
    self, message: discord.Message, anonymous: bool = False, plain: bool = False
) -> typing.Tuple[typing.List[discord.Message], discord.Message]:
    """Returns List[user_dm_msg] and thread_channel_msg"""
    if not message.content and not message.attachments and not message.stickers:
        raise MissingRequiredArgument(DummyParam("msg"))
    for guild in self.bot.guilds:
        try:
            if await self.bot.get_or_fetch_member(guild, self.id):
                break
        except discord.NotFound:
            pass
    else:
        return await message.channel.send(
            embed=discord.Embed(
                color=self.bot.error_color,
                description="Your message could not be delivered since "
                "the recipient shares no servers with the bot.",
            )
        )

    user_msg_tasks = []
    tasks = []

    for user in self.recipients:
        user_msg_tasks.append(
            self.send(
                message,
                destination=user,
                from_mod=True,
                anonymous=anonymous,
                plain=plain,
            )
        )

    try:
        user_msg = await asyncio.gather(*user_msg_tasks)
    except Exception as e:
        logger.error("Message delivery failed:", exc_info=True)
        user_msg = None
        if isinstance(e, discord.Forbidden):
            description = (
                "Your message could not be delivered as "
                "the recipient is only accepting direct "
                "messages from friends, or the bot was "
                "blocked by the recipient."
            )
        else:
            description = (
                "Your message could not be delivered due "
                "to an unknown error. Check `?debug` for "
                "more information"
            )
        msg = await message.channel.send(
            embed=discord.Embed(
                color=self.bot.error_color,
                description=description,
            )
        )
    else:
        # Send the same thing in the thread channel.
        msg = await self.send(
            message, destination=self.channel, from_mod=True, anonymous=anonymous, plain=plain
        )

        tasks.append(
            self.bot.api.append_log(
                message,
                message_id=msg.id,
                channel_id=self.channel.id,
                type_="anonymous" if anonymous else "thread_message",
            )
        )

        # Cancel closing if a thread message is sent.
        if self.close_task is not None:
            await self.cancel_closure()
            tasks.append(
                self.channel.send(
                    embed=discord.Embed(
                        color=self.bot.error_color,
                        description="Scheduled close has been cancelled.",
                    )
                )
            )

    await asyncio.gather(*tasks)
    self.bot.dispatch("thread_reply", self, True, message, anonymous, plain)
    return (user_msg, msg)  # sent_to_user, sent_to_thread_channel

async def send(
    self,
    message: discord.Message,
    destination: typing.Union[
        discord.TextChannel, discord.DMChannel, discord.User, discord.Member
    ] = None,
    from_mod: bool = False,
    note: bool = False,
    anonymous: bool = False,
    plain: bool = False,
    persistent_note: bool = False,
    thread_creation: bool = False,
) -> None:
    # Handle notes with Discord-like system message format - return early
    if note:
        destination = destination or self.channel
        content = message.content or "[No content]"

        # Create embed for note with Discord system message style
        embed = discord.Embed(
            description=content, color=0x5865F2  # Discord blurple color for system messages
        )

        # Set author with note icon and username
        if persistent_note:
            note_type = "Persistent Note"
        else:
            note_type = "Note"

        embed.set_author(
            name=f"📝 {note_type} ({message.author.name})", icon_url=message.author.display_avatar.url
        )

        # Add timestamp if enabled
        if self.bot.config["show_timestamp"]:
            embed.timestamp = message.created_at

        # Add a subtle footer to distinguish from replies
        if persistent_note:
            embed.set_footer(text="Persistent Internal Note")
        else:
            embed.set_footer(text="Internal Note")

        return await destination.send(embed=embed)

    if not note and from_mod:
        self.bot.loop.create_task(self._restart_close_timer())  # Start or restart thread auto close

    if self.close_task is not None:
        # cancel closing if a thread message is sent.
        self.bot.loop.create_task(self.cancel_closure())
        self.bot.loop.create_task(
            self.channel.send(
                embed=discord.Embed(
                    color=self.bot.error_color,
                    description="Scheduled close has been cancelled.",
                )
            )
        )

    if not self.ready:
        await self.wait_until_ready()

    if not from_mod and not note:
        self.bot.loop.create_task(self.bot.api.append_log(message, channel_id=self.channel.id))

    destination = destination or self.channel

    if destination is None:
        logger.error("Attempted to send a message to a thread with no channel (destination is None).")
        return
    try:
        await destination.typing()
    except discord.NotFound:
        logger.warning("Channel not found when trying to send message.")
        return

    author = message.author
    member = self.bot.guild.get_member(author.id)
    if member:
        avatar_url = member.display_avatar.url
    else:
        avatar_url = author.display_avatar.url

    # Handle forwarded messages first
    forwarded_jump_url = None
    if hasattr(message, "message_snapshots") and len(message.message_snapshots) > 0:
        snap = message.message_snapshots[0]
        # Only show "No content" if there's truly no content (no text, attachments, embeds, or stickers)
        if not snap.content and not message.attachments and not message.embeds and not message.stickers:
            content = "No content"
        else:
            content = snap.content or ""

        # Get jump_url from cached_message, fetch if not cached
        if hasattr(snap, "cached_message") and snap.cached_message is not None:
            forwarded_jump_url = snap.cached_message.jump_url
        else:
            if (
                hasattr(message, "reference")
                and message.reference
                and message.reference.type == discord.MessageReferenceType.forward
            ):
                try:
                    original_msg_channel = self.bot.get_channel(message.reference.channel_id)
                    original_msg = await original_msg_channel.fetch_message(message.reference.message_id)
                    forwarded_jump_url = original_msg.jump_url
                except (discord.NotFound, discord.Forbidden, AttributeError):
                    pass

        content = f"📨 **Forwarded message:**\n{content}" if content else "📨 **Forwarded message:**"
    else:
        # Only show "No content" if there's truly no content (no text, attachments, embeds, or stickers)
        if (
            not message.content
            and not message.attachments
            and not message.embeds
            and not message.stickers
        ):
            content = "No content"
        else:
            content = message.content or ""

    # Only set description if there's actual content to show
    if content:
        embed = discord.Embed(description=content)
    else:
        embed = discord.Embed()
    if self.bot.config["show_timestamp"]:
        embed.timestamp = message.created_at

    # Add forwarded message context
    if forwarded_jump_url:
        embed.add_field(name="Context", value=f"- {forwarded_jump_url}", inline=True)

    system_avatar_url = "https://discordapp.com/assets/f78426a064bc9dd24847519259bc42af.png"

    if not note:
        if anonymous and from_mod and not isinstance(destination, discord.TextChannel):
            # Anonymously sending to the user.
            tag = self.bot.config["mod_tag"]
            if tag is None:
                tag = str(get_top_role(author, self.bot.config["use_hoisted_top_role"]))
            name = self.bot.config["anon_username"]
            if name is None:
                name = tag
            avatar_url = self.bot.config["anon_avatar_url"]
            if avatar_url is None:
                avatar_url = self.bot.get_guild_icon(guild=self.bot.guild, size=128)
            embed.set_author(
                name=name,
                icon_url=avatar_url,
                url=f"https://discordapp.com/channels/{self.bot.guild.id}#{message.id}",
            )
        else:
            # Normal message
            name = str(author)
            avatar_url = avatar_url
            embed.set_author(
                name=name,
                icon_url=avatar_url,
                url=f"https://discordapp.com/users/{author.id}#{message.id}",
            )
    else:
        # Notes use system message style with note icon
        if persistent_note:
            note_type = "Persistent Note"
        else:
            note_type = "Note"

        embed.set_author(
            name=f"📝 {note_type} ({str(author)})",
            icon_url=avatar_url,
            url=f"https://discordapp.com/users/{author.id}#{message.id}",
        )
        embed.color = 0x5865F2  # Discord blurple for system messages

    ext = [(a.url, a.filename, False) for a in message.attachments]

    images = []
    attachments = []
    for attachment in ext:
        if is_image_url(attachment[0]):
            images.append(attachment)
        else:
            attachments.append(attachment)

    image_urls = re.findall(
        r"http[s]?:\/\/(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*(),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+",
        message.content,
    )

    image_urls = [
        (is_image_url(url, convert_size=False), None, False)
        for url in image_urls
        if is_image_url(url, convert_size=False)
    ]
    images.extend(image_urls)

    def lottie_to_png(data):
        importer = l_importers.get("lottie")
        exporter = l_exporters.get("png")
        with io.BytesIO() as stream:
            stream.write(data)
            stream.seek(0)
            an = importer.process(stream)

        with io.BytesIO() as stream:
            exporter.process(an, stream)
            stream.seek(0)
            return stream.read()

    for i in message.stickers:
        if i.format in (
            discord.StickerFormatType.png,
            discord.StickerFormatType.apng,
            discord.StickerFormatType.gif,
        ):
            images.append(
                (f"https://media.discordapp.net/stickers/{i.id}.{i.format.file_extension}", i.name, True)
            )
        elif i.format == discord.StickerFormatType.lottie:
            # save the json lottie representation
            try:
                async with self.bot.session.get(i.url) as resp:
                    data = await resp.read()

                # convert to a png
                img_data = await self.bot.loop.run_in_executor(
                    None, functools.partial(lottie_to_png, data)
                )
                b64_data = base64.b64encode(img_data).decode()

                # upload to imgur
                async with self.bot.session.post(
                    "https://api.imgur.com/3/image",
                    headers={"Authorization": "Client-ID 50e96145ac5e085"},
                    data={"image": b64_data},
                ) as resp:
                    result = await resp.json()
                    url = result["data"]["link"]

            except Exception:
                traceback.print_exc()
                images.append((None, i.name, True))
            else:
                images.append((url, i.name, True))
        else:
            images.append((None, i.name, True))

    embedded_image = False

    prioritize_uploads = any(i[1] is not None for i in images)

    additional_images = []
    additional_count = 1

    for url, filename, is_sticker in images:
        if (
            not prioritize_uploads or ((url is None or is_image_url(url)) and filename)
        ) and not embedded_image:
            if url is not None:
                embed.set_image(url=url)
            if filename:
                if is_sticker:
                    if url is None:
                        description = f"{filename}: Unable to retrieve sticker image"
                    else:
                        description = f"[{filename}]({url})"
                    embed.add_field(name="Sticker", value=description)
                else:
                    embed.add_field(name="Image", value=f"[{filename}]({url})")
            embedded_image = True
        else:
            if note:
                color = self.bot.main_color
            elif from_mod:
                color = self.bot.mod_color
            else:
                color = self.bot.recipient_color

            img_embed = discord.Embed(color=color)

            if url is not None:
                img_embed.set_image(url=url)
                img_embed.url = url
            if filename is not None:
                img_embed.title = filename
            img_embed.set_footer(text=f"Additional Image Upload ({additional_count})")
            img_embed.timestamp = message.created_at
            additional_images.append(destination.send(embed=img_embed))
            additional_count += 1

    file_upload_count = 1

    for url, filename, _ in attachments:
        embed.add_field(name=f"File upload ({file_upload_count})", value=f"[{filename}]({url})")
        file_upload_count += 1

    if from_mod:
        if note:
            # Notes use Discord blurple and special footer
            embed.colour = 0x5865F2
            if persistent_note:
                embed.set_footer(text="Persistent Internal Note")
            else:
                embed.set_footer(text="Internal Note")
        else:
            # Regular mod messages
            embed.colour = self.bot.mod_color
            # Anonymous reply sent in thread channel
            if anonymous and isinstance(destination, discord.TextChannel):
                embed.set_footer(text="Anonymous Reply")
            # Normal messages
            elif not anonymous:
                mod_tag = self.bot.config["mod_tag"]
                if mod_tag is None:
                    mod_tag = str(get_top_role(message.author, self.bot.config["use_hoisted_top_role"]))
                embed.set_footer(text=mod_tag)  # Normal messages
            else:
                embed.set_footer(text=self.bot.config["anon_tag"])
    else:
        # Add forwarded message indicator in footer for mods
        footer_text = f"Message ID: {message.id}"
        if hasattr(message, "message_snapshots") and len(message.message_snapshots) > 0:
            footer_text += " • Forwarded"
        embed.set_footer(text=footer_text)
        embed.colour = self.bot.recipient_color

    if (from_mod or note) and not thread_creation:
        delete_message = not bool(message.attachments)
        if delete_message and destination == self.channel:
            try:
                await message.delete()
            except Exception as e:
                logger.warning("Cannot delete message: %s.", e)

    if (
        from_mod
        and self.bot.config["dm_disabled"] == DMDisabled.ALL_THREADS
        and destination != self.channel
    ):
        logger.info("Sending a message to %s when DM disabled is set.", self.recipient)

    # Best-effort typing: never block message delivery if typing fails
    try:
        await destination.typing()
    except discord.NotFound:
        logger.warning("Channel not found.")
        raise
    except (discord.Forbidden, discord.HTTPException, Exception) as e:
        logger.warning("Unable to send typing to %s: %s. Continuing without typing.", destination, e)

    if not from_mod and not note:
        mentions = await self.get_notifications()
    else:
        mentions = None

    if plain:
        if from_mod and not isinstance(destination, discord.TextChannel):
            # Plain to user
            with warnings.catch_warnings():
                # Catch coroutines not awaited warning
                warnings.simplefilter("ignore")
                additional_images = []

            if embed.footer.text:
                plain_message = f"**{embed.footer.text} "
            else:
                plain_message = "**"
            plain_message += f"{embed.author.name}:** {embed.description}"
            files = []
            for i in message.attachments:
                files.append(await i.to_file())

            msg = await destination.send(plain_message, files=files)
        else:
            # Plain to mods
            embed.set_footer(text="[PLAIN] " + embed.footer.text)
            msg = await destination.send(mentions, embed=embed)

    else:
        msg = await destination.send(mentions, embed=embed)

    if additional_images:
        self.ready = False
        await asyncio.gather(*additional_images)
        self.ready = True

    return msg

async def find(
    self,
    *,
    recipient: typing.Union[discord.Member, discord.User] = None,
    channel: discord.TextChannel = None,
    recipient_id: int = None,
) -> typing.Optional[Thread]:
    """Finds a thread from cache or from discord channel topics."""
    if recipient is None and channel is not None and isinstance(channel, discord.TextChannel):
        if channel.id in self.closing:
            return None
        thread = await self._find_from_channel(channel)
        if thread is None:
            user_id, thread = next(
                ((k, v) for k, v in self.cache.items() if v.channel == channel), (-1, None)
            )
            if thread is not None:
                logger.debug("Found thread with tempered ID.")
                await channel.edit(topic=f"User ID: {user_id}")
        return thread

    if recipient:
        recipient_id = recipient.id

    thread = self.cache.get(recipient_id)
    if thread is not None:
        try:
            await thread.wait_until_ready()
        except asyncio.CancelledError:
            logger.warning("Thread for %s cancelled.", recipient)
            return thread
        else:
            # If the thread is snoozed (channel is None), return it for restoration
            if thread.cancelled:
                thread = None
    else:

        def check(topic):
            _, user_id, other_ids = parse_channel_topic(topic)
            return recipient_id == user_id or recipient_id in other_ids

        channel = discord.utils.find(
            lambda x: (check(x.topic)) if x.topic else False,
            self.bot.modmail_guild.text_channels,
        )

        if channel:
            thread = await Thread.from_channel(self, channel)
            if thread.recipient:
                # only save if data is valid.
                # also the recipient_id here could belong to other recipient,
                # it would be wrong if we set it as the dict key,
                # so we use the thread id instead
                self.cache[thread.id] = thread
            thread.ready = True

    if thread and recipient_id not in [x.id for x in thread.recipients]:
        self.cache.pop(recipient_id)
        thread = None

    return thread

