                # only save if data is valid.
                # also the recipient_id here could belong to other recipient,
                # it would be wrong if we set it as the dict key,
                # so we use the thread id instead
                self.cache[thread.id] = thread
            thread.ready = True

    if thread and recipient_id not in [x.id for x in thread.recipients]:
        self.cache.pop(recipient_id)
        thread = None

    return thread

def __init__(self, argument: str, *, now: Optional[datetime.datetime] = None):
    match = self.compiled.fullmatch(argument)
    if match is None or not match.group(0):
        match = self.discord_fmt.fullmatch(argument)
        if match is not None:
            self.dt = datetime.datetime.utcfromtimestamp(int(match.group("ts")), tz=datetime.timezone.utc)
            return
        else:
            raise commands.BadArgument("invalid time provided")

    data = {k: int(v) for k, v in match.groupdict(default=0).items()}
    now = now or datetime.datetime.now(datetime.timezone.utc)
    self.dt = now + relativedelta(**data)

def __init__(self, argument: str, *, now: Optional[datetime.datetime] = None):
    try:
        o = ShortTime(argument, now=now)
    except Exception:
        super().__init__(argument)
    else:
        self.dt = o.dt
        self._past = False

async def transform(self, interaction, value: str) -> datetime.datetime:
    now = interaction.created_at
    try:
        short = ShortTime(value, now=now)
    except commands.BadArgument:
        try:
            human = FutureTime(value, now=now)
        except commands.BadArgument as e:
            raise BadTimeTransform(str(e)) from None
        else:
            return human.dt
    else:
        return short.dt

def __init__(self, dt: datetime.datetime, now: datetime.datetime = None):
    self.dt = dt
    self.now = now

    if now is None:
        self.now = dt
    else:
        self.now = now

    self.arg = ""

def __init__(self, bot):
    self.bot = bot
    self._cache = {}
    self.ready_event = asyncio.Event()
    self.config_help = {}

async def refresh(self) -> dict:
    """Refreshes internal cache with data from database"""
    for k, v in (await self.bot.api.get_config()).items():
        k = k.lower()
        if k in self.all_keys:
            self._cache[k] = v
    if not self.ready_event.is_set():
        self.ready_event.set()
        logger.debug("Successfully fetched configurations from database.")
    return self._cache

def __setitem__(self, key: str, item: typing.Any) -> None:
    key = key.lower()
    logger.info("Setting %s.", key)
    if key not in self.all_keys:
        raise InvalidConfigError(f'Configuration "{key}" is invalid.')
    self._cache[key] = item

def __getitem__(self, key: str) -> typing.Any:
    # make use of the custom methods in func:get:
    return self.get(key)

def get(self, key: str, *, convert: bool = True) -> typing.Any:
    key = key.lower()
    if key not in self.all_keys:
        raise InvalidConfigError(f'Configuration "{key}" is invalid.')
    if key not in self._cache:
        self._cache[key] = deepcopy(self.defaults[key])
    value = self._cache[key]

    if not convert:
        return value

    if key in self.colors:
        try:
            return int(value.lstrip("#"), base=16)
        except ValueError:
            logger.error("Invalid %s provided.", key)
        value = int(self.remove(key).lstrip("#"), base=16)

    elif key in self.time_deltas:
        if not isinstance(value, isodate.Duration):
            try:
                value = isodate.parse_duration(value)
            except isodate.ISO8601Error:
                logger.warning(
                    "The {account} age limit needs to be a "
                    'ISO-8601 duration formatted duration, not "%s".',
                    value,
                )
                value = self.remove(key)

    elif key in self.booleans:
        try:
            value = strtobool(value)
        except ValueError:
            value = self.remove(key)

    elif key in self.enums:
        if value is None:
            return None
        try:
            value = self.enums[key](value)
        except ValueError:
            logger.warning("Invalid %s %s.", key, value)
            value = self.remove(key)

    elif key in self.force_str:
        # Temporary: as we saved in int previously, leading to int32 overflow,
        #            this is transitioning IDs to strings
        new_value = {}
        changed = False
        for k, v in value.items():
            new_v = v
            if isinstance(v, list):
                new_v = []
                for n in v:
                    if n != -1 and not isinstance(n, str):
                        changed = True
                        n = str(n)
                    new_v.append(n)
            new_value[k] = new_v

        if changed:
            # transition the database as well
            self.set(key, new_value)

        value = new_value

    return value

async def anonadduser(self, ctx, *users_arg: Union[discord.Member, discord.Role, str]):
    """Adds a user to a modmail thread anonymously

    `options` can be `silent` or `silently`.
    """
    silent = False
    users = []
    for u in users_arg:
        if isinstance(u, str):
            if "silent" in u or "silently" in u:
                silent = True
        elif isinstance(u, discord.Role):
            users += u.members
        elif isinstance(u, discord.Member):
            users.append(u)

    for u in users:
        curr_thread = await self.bot.threads.find(recipient=u)
        if curr_thread == ctx.thread:
            users.remove(u)
            continue

        if curr_thread:
            em = discord.Embed(
                title="Error",
                description=f"{u.mention} is already in a thread: {curr_thread.channel.mention}.",
                color=self.bot.error_color,
            )
            await ctx.send(embed=em)
            ctx.command.reset_cooldown(ctx)
            return

    if not users:
        em = discord.Embed(
            title="Error",
            description="All users are already in the thread.",
            color=self.bot.error_color,
        )
        await ctx.send(embed=em)
        ctx.command.reset_cooldown(ctx)
        return

    to_exec = []
    if not silent:
        em = discord.Embed(
            title=self.bot.config["private_added_to_group_title"],
            description=self.bot.config["private_added_to_group_description_anon"],
            color=self.bot.main_color,
        )
        if self.bot.config["show_timestamp"]:
            em.timestamp = discord.utils.utcnow()

        tag = self.bot.config["mod_tag"]
        if tag is None:
            tag = str(get_top_role(ctx.author, self.bot.config["use_hoisted_top_role"]))
        name = self.bot.config["anon_username"]
        if name is None:
            name = tag
        avatar_url = self.bot.config["anon_avatar_url"]
        if avatar_url is None:
            avatar_url = self.bot.get_guild_icon(guild=ctx.guild, size=128)
        em.set_footer(text=name, icon_url=avatar_url if avatar_url else None)

        for u in users:
            to_exec.append(u.send(embed=em))

        description = self.bot.formatter.format(
            self.bot.config["public_added_to_group_description_anon"],
            users=", ".join(u.name for u in users),
        )
        em = discord.Embed(
            title=self.bot.config["public_added_to_group_title"],
            description=description,
            color=self.bot.main_color,
        )
        if self.bot.config["show_timestamp"]:
            em.timestamp = discord.utils.utcnow()
        em.set_footer(
            text=f"{users[0]}", icon_url=users[0].display_avatar.url if users[0].display_avatar else None
        )

        for i in ctx.thread.recipients:
            if i not in users:
                to_exec.append(i.send(embed=em))

    await ctx.thread.add_users(users)
    if to_exec:
        await asyncio.gather(*to_exec)

    sent_emoji, _ = await self.bot.retrieve_emoji()
    await self.bot.add_reaction(ctx.message, sent_emoji)

