def _add_reasoning_system_prompt_if_needed(
    self, 
    messages: List[AllMessageValues], 
    optional_params: dict
) -> List[AllMessageValues]:
    """
    Add reasoning system prompt for Mistral magistral models when reasoning_effort is specified.
    """
    if not optional_params.get("_add_reasoning_prompt", False):
        return messages

    # Check if there's already a system message
    has_system_message = any(msg.get("role") == "system" for msg in messages)

    if has_system_message:
        # Prepend reasoning instructions to existing system message
        for i, msg in enumerate(messages):
            if msg.get("role") == "system":
                existing_content = msg.get("content", "")
                reasoning_prompt = self._get_mistral_reasoning_system_prompt()

                # Handle both string and list content
                if isinstance(existing_content, str):
                    # String content - prepend reasoning prompt
                    new_content = f"{reasoning_prompt}\n\n{existing_content}"
                elif isinstance(existing_content, list):
                    # List content - prepend reasoning prompt as text block
                    new_content = [
                        {"type": "text", "text": reasoning_prompt + "\n\n"}
                    ] + existing_content
                else:
                    # Fallback for any other type - convert to string
                    new_content = f"{reasoning_prompt}\n\n{str(existing_content)}"

                messages[i] = cast(AllMessageValues, {
                    **msg,
                    "content": new_content
                })
                break
    else:
        # Add new system message with reasoning instructions
        reasoning_message: AllMessageValues = cast(AllMessageValues, {
            "role": "system",
            "content": self._get_mistral_reasoning_system_prompt()
        })
        messages = [reasoning_message] + messages

    # Remove the internal flag
    optional_params.pop("_add_reasoning_prompt", None)
    return messages

def _add_reasoning_system_prompt_if_needed(
    self, 
    messages: List[AllMessageValues], 
    optional_params: dict
) -> List[AllMessageValues]:
    """
    Add reasoning system prompt for Mistral magistral models when reasoning_effort is specified.
    """
    if not optional_params.get("_add_reasoning_prompt", False):
        return messages

    # Check if there's already a system message
    has_system_message = any(msg.get("role") == "system" for msg in messages)

    if has_system_message:
        # Prepend reasoning instructions to existing system message
        for i, msg in enumerate(messages):
            if msg.get("role") == "system":
                existing_content = msg.get("content", "")
                reasoning_prompt = self._get_mistral_reasoning_system_prompt()

                # Handle both string and list content
                if isinstance(existing_content, str):
                    # String content - prepend reasoning prompt
                    new_content = f"{reasoning_prompt}\n\n{existing_content}"
                elif isinstance(existing_content, list):
                    # List content - prepend reasoning prompt as text block
                    new_content = [
                        {"type": "text", "text": reasoning_prompt + "\n\n"}
                    ] + existing_content
                else:
                    # Fallback for any other type - convert to string
                    new_content = f"{reasoning_prompt}\n\n{str(existing_content)}"

                messages[i] = cast(AllMessageValues, {
                    **msg,
                    "content": new_content
                })
                break
    else:
        # Add new system message with reasoning instructions
        reasoning_message: AllMessageValues = cast(AllMessageValues, {
            "role": "system",
            "content": self._get_mistral_reasoning_system_prompt()
        })
        messages = [reasoning_message] + messages

    # Remove the internal flag
    optional_params.pop("_add_reasoning_prompt", None)
    return messages

async def model_info_v1(  # noqa: PLR0915
    user_api_key_dict: UserAPIKeyAuth = Depends(user_api_key_auth),
    litellm_model_id: Optional[str] = None,
):
    """
    Provides more info about each model in /models, including config.yaml descriptions (except api key and api base)

    Parameters:
        litellm_model_id: Optional[str] = None (this is the value of `x-litellm-model-id` returned in response headers)

        - When litellm_model_id is passed, it will return the info for that specific model
        - When litellm_model_id is not passed, it will return the info for all models

    Returns:
        Returns a dictionary containing information about each model.

    Example Response:
    ```json
    {
        "data": [
                    {
                        "model_name": "fake-openai-endpoint",
                        "litellm_params": {
                            "api_base": "https://exampleopenaiendpoint-production.up.railway.app/",
                            "model": "openai/fake"
                        },
                        "model_info": {
                            "id": "112f74fab24a7a5245d2ced3536dd8f5f9192c57ee6e332af0f0512e08bed5af",
                            "db_model": false
                        }
                    }
                ]
    }

    ```
    """
    global llm_model_list, general_settings, user_config_file_path, proxy_config, llm_router, user_model

    if user_model is not None:
        # user is trying to get specific model from litellm router
        try:
            model_info: Dict = cast(Dict, litellm.get_model_info(model=user_model))
        except Exception:
            model_info = {}
        _deployment_info = Deployment(
            model_name="*",
            litellm_params=LiteLLM_Params(
                model=user_model,
            ),
            model_info=model_info,
        )
        _deployment_info_dict = _deployment_info.model_dump()
        _deployment_info_dict = remove_sensitive_info_from_deployment(
            deployment_dict=_deployment_info_dict
        )
        return {"data": _deployment_info_dict}

    if llm_model_list is None:
        raise HTTPException(
            status_code=500,
            detail={
                "error": "LLM Model List not loaded in. Make sure you passed models in your config.yaml or on the LiteLLM Admin UI. - https://docs.litellm.ai/docs/proxy/configs"
            },
        )

    if llm_router is None:
        raise HTTPException(
            status_code=500,
            detail={
                "error": "LLM Router is not loaded in. Make sure you passed models in your config.yaml or on the LiteLLM Admin UI. - https://docs.litellm.ai/docs/proxy/configs"
            },
        )

    if litellm_model_id is not None:
        # user is trying to get specific model from litellm router
        deployment_info = llm_router.get_deployment(model_id=litellm_model_id)
        if deployment_info is None:
            raise HTTPException(
                status_code=400,
                detail={
                    "error": f"Model id = {litellm_model_id} not found on litellm proxy"
                },
            )
        _deployment_info_dict = _get_proxy_model_info(
            model=deployment_info.model_dump(exclude_none=True)
        )
        return {"data": [_deployment_info_dict]}

    all_models: List[dict] = []
    model_access_groups: Dict[str, List[str]] = defaultdict(list)
    ## CHECK IF MODEL RESTRICTIONS ARE SET AT KEY/TEAM LEVEL ##
    if llm_router is None:
        proxy_model_list = []
    else:
        proxy_model_list = llm_router.get_model_names()
        model_access_groups = llm_router.get_model_access_groups()
    key_models = get_key_models(
        user_api_key_dict=user_api_key_dict,
        proxy_model_list=proxy_model_list,
        model_access_groups=model_access_groups,
    )
    team_models = get_team_models(
        team_models=user_api_key_dict.team_models,
        proxy_model_list=proxy_model_list,
        model_access_groups=model_access_groups,
    )
    all_models_str = get_complete_model_list(
        key_models=key_models,
        team_models=team_models,
        proxy_model_list=proxy_model_list,
        user_model=user_model,
        infer_model_from_keys=general_settings.get("infer_model_from_keys", False),
        llm_router=llm_router,
    )

    if len(all_models_str) > 0:
        _relevant_models = []
        for model in all_models_str:
            router_models = llm_router.get_model_list(model_name=model)
            if router_models is not None:
                _relevant_models.extend(router_models)
        if llm_model_list is not None:
            all_models = copy.deepcopy(_relevant_models)  # type: ignore
        else:
            all_models = []

    for in_place_model in all_models:
        in_place_model = _get_proxy_model_info(model=in_place_model)

    verbose_proxy_logger.debug("all_models: %s", all_models)
    return {"data": all_models}

