def __process_content_provider(self, state: State, path: str, query: t.Dict[str, str]):
    variable_name = query.get("variable_name")
    content = None
    if variable_name:
        content = _getscopeattr(self, variable_name)  # type: ignore[arg-type]
        if isinstance(content, _TaipyContentHtml):
            content = content.get()
        provider_fn = Gui.__content_providers.get(type(content))
        if provider_fn is None:
            # try plotly
            if _module_exists("plotly.graph_objs"):
                from plotly.graph_objs import Figure as PlotlyFigure  # type: ignore[reportMissingImports]

                if isinstance(content, PlotlyFigure):

                    def get_plotly_content(figure: PlotlyFigure):
                        return figure.to_html()

                    Gui.register_content_provider(PlotlyFigure, get_plotly_content)
                    provider_fn = get_plotly_content
        if provider_fn is None:
            # try matplotlib
            if _module_exists("matplotlib.figure"):
                from matplotlib.figure import Figure as MatplotlibFigure

                if isinstance(content, MatplotlibFigure):

                    def get_matplotlib_content(figure: MatplotlibFigure):
                        import base64
                        from io import BytesIO

                        buf = BytesIO()
                        figure.savefig(buf, format="png")
                        data = base64.b64encode(buf.getbuffer()).decode("ascii")
                        return f'<img src="data:image/png;base64,{data}"/>'

                    Gui.register_content_provider(MatplotlibFigure, get_matplotlib_content)
                    provider_fn = get_matplotlib_content

        if _is_function(provider_fn):
            try:
                return t.cast(t.Callable, provider_fn)(t.cast(t.Any, content))
            except Exception as e:
                _warn(f"Error in content provider for type {str(type(content))}", e)
    return (
        '<div style="background:white;color:red;">'
        + (f"No valid provider for type {type(content).__name__}" if content else "Wrong context.")
        + "</div>"
    )

def parse(self, o):
    try:
        for adapter in reversed(self._adapters):
            if (output := adapter.parse(o)) is not None:
                return output
        raise TypeError(f"Object of type {type(o).__name__} is not JSON serializable (value: {o}).")
    except Exception as e:
        _warn("Exception while resolving JSON", e)
        return None

def parse(self, o):
    if isinstance(o, Icon):
        return o._to_dict()
    if isinstance(o, _MapDict):
        return o._dict
    if isinstance(o, _TaipyBase):
        return o.get()
    if isinstance(o, (datetime, date, time)):
        return _date_to_string(o)
    if isinstance(o, Path):
        return str(o)
    if isinstance(o, (timedelta, pandas.Timedelta)):
        return str(o)
    if isinstance(o, numpy.generic):
        return getattr(o, "tolist", lambda: o)()
    if isinstance(o, _DoNotUpdate):
        return None

def check_changed_files_coverage(coverage_file, changed_files, threshold=80):
    """Check the coverage of changed files."""
    with open(coverage_file) as f:
        data = xmltodict.parse(f.read())

    # Handle multiple packages in the coverage report
    packages = data["coverage"]["packages"]["package"]
    if not isinstance(packages, list):
        packages = [packages]

    # Extract coverage data for all files
    files = {}
    for package in packages:
        classes = package["classes"]["class"]
        if not isinstance(classes, list):
            classes = [classes]
        for cls in classes:
            files[cls["@filename"]] = float(cls["@line-rate"]) * 100
    qty = 0
    sum_coverage = 0
    for file in changed_files:
        if file in files:
            coverage = files[file]
            print(f"Coverage for {file}: {coverage:.2f}%")  # noqa: T201
            sum_coverage += coverage
            qty += 1
        else:
            print(f"No coverage data found for {file}")  # noqa: T201

    if qty:
        if sum_coverage / qty < threshold:
            print(f"Coverage for changed files is below {threshold}%: {sum_coverage/qty:.2f}%")  # noqa: T201
            sys.exit(1)
        print(f"Coverage for changed files: {sum_coverage/qty:.2f}%")  # noqa: T201
    else:
        print("No file detected to run coverage for.")  # noqa: T201

