def _get_client_id(self) -> str:
    return (
        _DataScopes._GLOBAL_ID
        if self._bindings()._is_single_client()
        else getattr(get_server_request_accessor(self).get_request_meta(), Gui.__ARG_CLIENT_ID, "unknown id")
    )

def __set_client_id_in_context(self, client_id: t.Optional[str] = None, force=False):
    if not client_id and get_server_request_accessor(self).get_request():
        client_id = get_server_request_accessor(self).arg(Gui.__ARG_CLIENT_ID, "")
    if not client_id and (
        ws_client_id := getattr(get_server_request_accessor(self).get_request_meta(), "ws_client_id", None)
    ):
        client_id = ws_client_id
    if not client_id and force:
        res = self._bindings()._get_or_create_scope("")
        client_id = res[0] if res[1] else None
    if client_id:
        if sid := get_server_request_accessor(self).sid():
            sids = self.__client_id_2_sid.get(client_id, None)
            if sids is None:
                sids = set()
                self.__client_id_2_sid[client_id] = sids
            sids.add(sid)
    get_server_request_accessor(self).get_request_meta().client_id = client_id

def __is_var_modified_in_context(self, var_name: str, derived_vars: t.Set[str]) -> bool:
    modified_vars: t.Optional[t.Set[str]] = getattr(
        get_server_request_accessor(self).get_request_meta(), "modified_vars", None
    )
    der_vars: t.Optional[t.Set[str]] = getattr(
        get_server_request_accessor(self).get_request_meta(), "derived_vars", None
    )
    get_server_request_accessor(self).get_request_meta().update_count = (
        getattr(get_server_request_accessor(self).get_request_meta(), "update_count", 0) + 1
    )  # noqa: B010
    if modified_vars is None:
        modified_vars = set()
        get_server_request_accessor(self).get_request_meta().modified_vars = modified_vars
    if der_vars is None:
        get_server_request_accessor(self).get_request_meta().derived_vars = derived_vars
    else:
        der_vars.update(derived_vars)
    if var_name in modified_vars:
        return True
    modified_vars.add(var_name)
    return False

def __clean_vars_on_exit(self) -> t.Optional[t.Set[str]]:
    update_count = getattr(get_server_request_accessor(self).get_request_meta(), "update_count", 0) - 1
    if update_count < 1:
        derived_vars: t.Set[str] = getattr(
            get_server_request_accessor(self).get_request_meta(), "derived_vars", set()
        )
        delattr(get_server_request_accessor(self).get_request_meta(), "update_count")
        delattr(get_server_request_accessor(self).get_request_meta(), "modified_vars")
        delattr(get_server_request_accessor(self).get_request_meta(), "derived_vars")
        return derived_vars
    else:
        setattr(get_server_request_accessor(self).get_request_meta(), "update_count", update_count)  # noqa: B010
        return None

def _handle_disconnect(self):
    _Hooks()._handle_disconnect(self)
    if (sid := get_server_request_accessor(self).sid()) and (
        st_to := self._get_config("state_retention_period", 0)
    ) > 0:
        for cl_id, sids in self.__client_id_2_sid.items():
            if sid in sids:
                if len(sids) == 1:
                    Timer(st_to, self._remove_state, [cl_id]).start()
                else:
                    sids.remove(sid)
                return

def _manage_ws_message(self, msg_type: _WsType, message: dict) -> None:
    try:
        client_id = None
        if msg_type == _WsType.CLIENT_ID.value:
            payload = message.get("payload", {})
            res = self._bindings()._get_or_create_scope(
                payload.get("id", "") if isinstance(payload, dict) else str(payload)
            )
            client_id = res[0] if res[1] else None
            front_gui_addr = payload.get("gui_addr", None) if isinstance(payload, dict) else None
            if front_gui_addr is not None:
                self.__handle_ws_gui_addr({"name": message.get("name"), "payload": front_gui_addr})
        expected_client_id = client_id or message.get(Gui.__ARG_CLIENT_ID)
        self.__set_client_id_in_context(expected_client_id)
        get_server_request_accessor(self).get_request_meta().ws_client_id = expected_client_id
        with self._set_locals_context(message.get("module_context") or None):
            with self._get_authorization():
                payload = message.get("payload", {})
                if msg_type == _WsType.UPDATE.value:
                    self.__front_end_update(
                        str(message.get("name")),
                        payload.get("value"),
                        message.get("propagate", True),
                        payload.get("relvar"),
                        payload.get("on_change"),
                    )
                elif msg_type == _WsType.ACTION.value:
                    self.__on_action(message.get("name"), message.get("payload"))
                elif msg_type == _WsType.DATA_UPDATE.value:
                    self.__request_data_update(str(message.get("name")), message.get("payload"))
                elif msg_type == _WsType.REQUEST_UPDATE.value:
                    self.__request_var_update(message.get("payload"))
                elif msg_type == _WsType.GUI_ADDR.value:
                    self.__handle_ws_gui_addr(message)
                elif msg_type == _WsType.LOCAL_STORAGE.value:
                    self.__handle_ws_local_storage(message)
                else:
                    self._manage_external_message(msg_type, message)
            self.__send_ack(message.get("ack_id"))
    except Exception as e:  # pragma: no cover
        if isinstance(e, AttributeError) and (name := message.get("name")):
            try:
                names = self._get_real_var_name(name)
                var_name = names[0] if isinstance(names, tuple) else names
                var_context = names[1] if isinstance(names, tuple) else None
                if var_name.startswith("tpec_"):
                    var_name = var_name[5:]
                if var_name.startswith("TpExPr_"):
                    var_name = var_name[7:]
                _warn(
                    f"A problem occurred while resolving variable '{var_name}'"
                    + (f" in module '{var_context}'." if var_context else ".")
                )
            except Exception as e1:
                _warn(f"Resolving  name '{name}' failed", e1)
        else:
            _warn(f"Decoding Message has failed: {message}", e)

def __front_end_update(
    self,
    var_name: str,
    value: t.Any,
    propagate=True,
    rel_var: t.Optional[str] = None,
    on_change: t.Optional[str] = None,
) -> None:
    if not var_name or "." in var_name:
        return
    # Check if Variable is a managed type
    current_value = _getscopeattr_drill(self, self.__evaluator.get_hash_from_expr(var_name))  # type: ignore[arg-type]
    if isinstance(current_value, _TaipyData):
        return
    elif rel_var and isinstance(current_value, _TaipyLovValue):  # pragma: no cover
        lov_holder = _getscopeattr_drill(self, self.__evaluator.get_hash_from_expr(rel_var))  # type: ignore[arg-type]
        if isinstance(lov_holder, _TaipyLov):
            if isinstance(value, (str, list)):
                val = value if isinstance(value, list) else [value]
                elt_4_ids = self.__adapter._get_elt_per_ids(lov_holder.get_name(), lov_holder.get())
                ret_val = [elt_4_ids.get(x, x) for x in val]
                if isinstance(value, list):
                    value = ret_val
                elif ret_val:
                    value = ret_val[0]
    elif isinstance(current_value, _TaipyBase):
        value = current_value.cast_value(value)
    self._update_var(
        var_name, value, propagate, current_value if isinstance(current_value, _TaipyBase) else None, on_change
    )

def _update_var(
    self,
    var_name: str,
    value: t.Any,
    propagate=True,
    holder: t.Optional[_TaipyBase] = None,
    on_change: t.Optional[str] = None,
    forward: t.Optional[bool] = True,
) -> None:
    if holder:
        var_name = holder.get_name()
    hash_expr = self.__evaluator.get_hash_from_expr(var_name)
    derived_vars = {hash_expr}
    # set to broadcast mode if hash_expr is in shared_variable
    if hash_expr in self._get_shared_variables():
        self._set_broadcast()
    # Use custom attrsetter function to allow value binding for _MapDict
    if propagate:
        _setscopeattr_drill(self, hash_expr, value)  # type: ignore[arg-type]
        # In case expression == hash (which is when there is only a single variable in expression)
        if var_name == hash_expr or hash_expr.startswith("tpec_"):
            derived_vars.update(self._re_evaluate_expr(var_name))
    elif holder:
        derived_vars.update(self._evaluate_holders(hash_expr))
    if forward:
        # if the variable has been evaluated then skip updating to prevent infinite loop
        var_modified = self.__is_var_modified_in_context(hash_expr, derived_vars)
        if not var_modified:
            self._call_on_change(
                var_name,
                value.get()
                if isinstance(value, _TaipyBase)
                else value._dict
                if isinstance(value, _MapDict)
                else value,
                on_change,
            )
        derived_modified = self.__clean_vars_on_exit()
        if derived_modified is not None:
            self.__send_var_list_update(list(derived_modified), var_name)

def _get_real_var_name(self, var_name: str) -> t.Tuple[str, str]:
    if not var_name:
        return (var_name, var_name)
    # Handle holder prefix if needed
    if var_name.startswith(_TaipyBase._HOLDER_PREFIX):
        for hp in _TaipyBase._get_holder_prefixes():
            if var_name.startswith(hp):
                var_name = var_name[len(hp) :]
                break
    suffix_var_name = ""
    if "." in var_name:
        first_dot_index = var_name.index(".")
        suffix_var_name = var_name[first_dot_index + 1 :]
        var_name = var_name[:first_dot_index]
    var_name_decode, module_name = _variable_decode(self._get_expr_from_hash(var_name))
    current_context = self._get_locals_context()
    # #583: allow module resolution for var_name in current_context root_page context
    if (
        module_name
        and self._config.root_page
        and self._config.root_page._renderer
        and self._config.root_page._renderer._get_module_name() == module_name
    ):
        return f"{var_name_decode}.{suffix_var_name}" if suffix_var_name else var_name_decode, module_name
    if module_name == current_context:
        var_name = var_name_decode
    # only strict checking for cross-context linked variable when the context has been properly set
    elif self._has_set_context():
        if var_name not in self.__var_dir._var_head:
            raise NameError(f"Can't find matching variable for {var_name} on context: {current_context}")
        _found = False
        for k, v in self.__var_dir._var_head[var_name]:
            if v == current_context:
                var_name = k
                _found = True
                break
        if not _found:  # pragma: no cover
            raise NameError(f"Can't find matching variable for {var_name} on context: {current_context}")
    return f"{var_name}.{suffix_var_name}" if suffix_var_name else var_name, current_context

def _call_on_change(self, var_name: str, value: t.Any, on_change: t.Optional[str] = None):
    try:
        var_name, current_context = self._get_real_var_name(var_name)
    except Exception as e:  # pragma: no cover
        _warn("", e)
        return
    on_change_fn = self._get_user_function(on_change) if on_change else None
    if not _is_function(on_change_fn):
        on_change_fn = self._get_user_function("on_change")
    if _is_function(on_change_fn):
        try:
            self._call_function_with_state(t.cast(t.Callable, on_change_fn), [var_name, value, current_context])
        except Exception as e:  # pragma: no cover
            if not self._call_on_exception(on_change or "on_change", e):
                _warn(f"{on_change or 'on_change'}(): callback function raised an exception", e)

def _init_route(self):
    self.__set_client_id_in_context(force=True)
    if not _hasscopeattr(self, Gui.__ON_INIT_NAME):  # type: ignore[arg-type]
        _setscopeattr(self, Gui.__ON_INIT_NAME, True)  # type: ignore[arg-type]
        self.__pre_render_pages()
        self.__init_libs()
        if hasattr(self, "on_init") and _is_function(self.on_init):
            try:
                self._call_function_with_state(t.cast(t.Callable, self.on_init))
            except Exception as e:  # pragma: no cover
                if not self._call_on_exception("on_init", e):
                    _warn("Exception raised in on_init()", e)
    return self._render_route()

def get_server_instance(self):
    """Get the internal server application.

    This method must be called **after** `(Gui.)run()^` was invoked.

    Returns:
        The server instance used.
    """
    if hasattr(self, "_server"):
        return self._server.get_server_instance()
    raise RuntimeError("get_server_instance() cannot be invoked before run() has been called.")

def __init__(self, *args, **kwargs) -> None:
    self._properties: t.Dict[str, t.Any] = {}
    self._lambdas: t.Dict[str, str] = {}
    self.__calling_frame = t.cast(
        FrameType, t.cast(FrameType, t.cast(FrameType, inspect.currentframe()).f_back).f_back
    )

    if args and self._DEFAULT_PROPERTY != "":
        self._properties = {self._DEFAULT_PROPERTY: args[0]}
    # special attribute for inline
    self._is_inline = kwargs.pop("inline", False)
    self._properties.update(kwargs)
    self.parse_properties()

def _evaluate_lambdas(self, gui: Gui):
    for k, lmbd in self._lambdas.items():
        expr = gui._evaluate_expr(lmbd, lambda_expr=True)
        gui._bind_var_val(k, _getscopeattr(gui, expr))

def __parse_lambda_property(self, key: str, value: t.Any) -> t.Any:
    try:
        source = inspect.findsource(value)
        st = ast.parse("".join(source[0]))
        lambda_by_name: t.Dict[str, ast.Lambda] = {}
        _LambdaByName(self._ELEMENT_NAME, source[1], lambda_by_name).visit(st)
        lambda_fn = lambda_by_name.get(
            key,
            lambda_by_name.get(_LambdaByName._DEFAULT_NAME, None) if key == self._DEFAULT_PROPERTY else None,
        )
        if lambda_fn is None:
            return None
        args = [arg.arg for arg in lambda_fn.args.args]
        targets = [
            comprehension.target.id  # type: ignore[attr-defined]
            for node in ast.walk(lambda_fn.body)
            if isinstance(node, ast.ListComp)
            for comprehension in node.generators
        ]
        tree = _TransformVarToValue(self.__calling_frame, args + targets + _python_builtins).visit(lambda_fn)
        ast.fix_missing_locations(tree)
        lambda_text = ast.unparse(tree)
        lambda_name = _get_lambda_id(value, index=(_Element.__get_lambda_index()))
        self._lambdas[lambda_name] = lambda_text
        return f'{{{lambda_name}({", ".join(args)})}}'
    except Exception as e:
        _warn("Error in lambda expression", e)
    return None

def set_config_env_vars(args: dict):
    """
    Convert API arguments into environment variables.
    Handles nested dictionaries, lists, and special values.

    Args:
        args (dict): The arguments dictionary from the API request
    """

    def process_value(value):
        """Convert Python values to string format for environment variables"""
        if value is None:
            return ""
        if isinstance(value, bool):
            return str(value).lower()
        if isinstance(value, (list, dict)):
            return str(value)
        return str(value)

    def set_env_vars(data, prefix=""):
        """Recursively set environment variables from nested dictionary"""
        for key, value in data.items():
            env_key = prefix + key.upper()

            # Handle special cases
            if isinstance(value, dict):
                # For nested dictionaries (like special_tokens)
                set_env_vars(value, f"{env_key}_")
            elif isinstance(value, list):
                # Handle list of dictionaries (like datasets)
                if value and isinstance(value[0], dict):
                    for i, item in enumerate(value):
                        set_env_vars(item, f"{env_key}_{i}_")
                else:
                    # For simple lists (like lora_target_modules)
                    os.environ[env_key] = process_value(value)
            else:
                # Handle all other cases
                os.environ[env_key] = process_value(value)

    # Clear any existing related environment variables
    # This prevents old values from persisting
    for key in list(os.environ.keys()):
        if key.startswith(
            ("BASE_MODEL", "MODEL_TYPE", "TOKENIZER_TYPE", "DATASET", "LORA_", "WANDB_")
        ):
            del os.environ[key]

    # Set new environment variables
    set_env_vars(args)

