def _format_mcp_result(self, result: Any) -> str:
	"""Format MCP tool result into a string for ActionResult.

	Args:
		result: Raw result from MCP tool call

	Returns:
		Formatted string representation of the result
	"""
	# Handle different MCP result formats
	if hasattr(result, 'content'):
		# Structured content response
		if isinstance(result.content, list):
			# Multiple content items
			parts = []
			for item in result.content:
				if hasattr(item, 'text'):
					parts.append(item.text)
				elif hasattr(item, 'type') and item.type == 'text':
					parts.append(str(item))
				else:
					parts.append(str(item))
			return '\n'.join(parts)
		else:
			return str(result.content)
	elif isinstance(result, list):
		# List of content items
		parts = []
		for item in result:
			if hasattr(item, 'text'):
				parts.append(item.text)
			else:
				parts.append(str(item))
		return '\n'.join(parts)
	else:
		# Direct result or unknown format
		return str(result)

def are_images_identical(img_path1: str, img_path2: str) -> bool:
	"""Check if two images are identical by comparing their content."""
	try:
		with Image.open(img_path1) as img1, Image.open(img_path2) as img2:
			# Convert to same format for comparison
			if img1.mode != img2.mode:
				img1 = img1.convert('RGB')
				img2 = img2.convert('RGB')

			# Compare sizes first (quick check)
			if img1.size != img2.size:
				return False

			# Compare pixel data
			return list(img1.getdata()) == list(img2.getdata())
	except Exception as e:
		logger.warning(f'Failed to compare images {img_path1} and {img_path2}: {e}')
		return False

