def _use(
    self,
    tool_string: str,
    tool: CrewStructuredTool,
    calling: Union[ToolCalling, InstructorToolCalling],
) -> str:
    if self._check_tool_repeated_usage(calling=calling):  # type: ignore # _check_tool_repeated_usage of "ToolUsage" does not return a value (it only ever returns None)
        try:
            result = self._i18n.errors("task_repeated_usage").format(
                tool_names=self.tools_names
            )
            self._telemetry.tool_repeated_usage(
                llm=self.function_calling_llm,
                tool_name=tool.name,
                attempts=self._run_attempts,
            )
            result = self._format_result(result=result)  # type: ignore #  "_format_result" of "ToolUsage" does not return a value (it only ever returns None)
            return result  # type: ignore # Fix the return type of this function

        except Exception:
            if self.task:
                self.task.increment_tools_errors()

    if self.agent:
        event_data = {
            "agent_key": self.agent.key,
            "agent_role": self.agent.role,
            "tool_name": self.action.tool,
            "tool_args": self.action.tool_input,
            "tool_class": self.action.tool,
            "agent": self.agent,
        }

        if self.agent.fingerprint:
            event_data.update(self.agent.fingerprint)

        crewai_event_bus.emit(self,ToolUsageStartedEvent(**event_data))

    started_at = time.time()
    from_cache = False
    result = None  # type: ignore

    if self.tools_handler and self.tools_handler.cache:
        result = self.tools_handler.cache.read(
            tool=calling.tool_name, input=calling.arguments
        )  # type: ignore
        from_cache = result is not None

    available_tool = next(
        (
            available_tool
            for available_tool in self.tools
            if available_tool.name == tool.name
        ),
        None,
    )

    usage_limit_error = self._check_usage_limit(available_tool, tool.name)
    if usage_limit_error:
        try:
            result = usage_limit_error
            self._telemetry.tool_usage_error(llm=self.function_calling_llm)
            result = self._format_result(result=result)
            return result
        except Exception:
            if self.task:
                self.task.increment_tools_errors()

    if result is None:
        try:
            if calling.tool_name in [
                "Delegate work to coworker",
                "Ask question to coworker",
            ]:
                coworker = (
                    calling.arguments.get("coworker") if calling.arguments else None
                )
                if self.task:
                    self.task.increment_delegations(coworker)

            if calling.arguments:
                try:
                    acceptable_args = tool.args_schema.model_json_schema()[
                        "properties"
                    ].keys()  # type: ignore
                    arguments = {
                        k: v
                        for k, v in calling.arguments.items()
                        if k in acceptable_args
                    }
                    # Add fingerprint metadata if available
                    arguments = self._add_fingerprint_metadata(arguments)
                    result = tool.invoke(input=arguments)
                except Exception:
                    arguments = calling.arguments
                    # Add fingerprint metadata if available
                    arguments = self._add_fingerprint_metadata(arguments)
                    result = tool.invoke(input=arguments)
            else:
                # Add fingerprint metadata even to empty arguments
                arguments = self._add_fingerprint_metadata({})
                result = tool.invoke(input=arguments)
        except Exception as e:
            self.on_tool_error(tool=tool, tool_calling=calling, e=e)
            self._run_attempts += 1
            if self._run_attempts > self._max_parsing_attempts:
                self._telemetry.tool_usage_error(llm=self.function_calling_llm)
                error_message = self._i18n.errors("tool_usage_exception").format(
                    error=e, tool=tool.name, tool_inputs=tool.description
                )
                error = ToolUsageErrorException(
                    f"\n{error_message}.\nMoving on then. {self._i18n.slice('format').format(tool_names=self.tools_names)}"
                ).message
                if self.task:
                    self.task.increment_tools_errors()
                if self.agent and self.agent.verbose:
                    self._printer.print(
                        content=f"\n\n{error_message}\n", color="red"
                    )
                return error  # type: ignore # No return value expected

            if self.task:
                self.task.increment_tools_errors()
            return self.use(calling=calling, tool_string=tool_string)  # type: ignore # No return value expected

        if self.tools_handler:
            should_cache = True
            if (
                hasattr(available_tool, "cache_function")
                and available_tool.cache_function  # type: ignore # Item "None" of "Any | None" has no attribute "cache_function"
            ):
                should_cache = available_tool.cache_function(  # type: ignore # Item "None" of "Any | None" has no attribute "cache_function"
                    calling.arguments, result
                )

            self.tools_handler.on_tool_use(
                calling=calling, output=result, should_cache=should_cache
            )
    self._telemetry.tool_usage(
        llm=self.function_calling_llm,
        tool_name=tool.name,
        attempts=self._run_attempts,
    )
    result = self._format_result(result=result)  # type: ignore # "_format_result" of "ToolUsage" does not return a value (it only ever returns None)
    data = {
        "result": result,
        "tool_name": tool.name,
        "tool_args": calling.arguments,
    }

    self.on_tool_use_finished(
        tool=tool,
        tool_calling=calling,
        from_cache=from_cache,
        started_at=started_at,
        result=result,
    )

    if (
        hasattr(available_tool, "result_as_answer")
        and available_tool.result_as_answer  # type: ignore # Item "None" of "Any | None" has no attribute "cache_function"
    ):
        result_as_answer = available_tool.result_as_answer  # type: ignore # Item "None" of "Any | None" has no attribute "result_as_answer"
        data["result_as_answer"] = result_as_answer  # type: ignore

    if self.agent and hasattr(self.agent, "tools_results"):
        self.agent.tools_results.append(data)

    if available_tool and hasattr(available_tool, 'current_usage_count'):
        available_tool.current_usage_count += 1
        if hasattr(available_tool, 'max_usage_count') and available_tool.max_usage_count is not None:
            self._printer.print(
                content=f"Tool '{available_tool.name}' usage: {available_tool.current_usage_count}/{available_tool.max_usage_count}",
                color="blue"
            )

    return result

